def get_ticket_fields(account_id, workspace_id=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    events = _load("integration_events.json")
    accounts = _load("fs_accounts.json")
    tickets = _load("tickets.json")
    catalog = _load("catalog_and_kb.json")

    # Prepare queued event (will be finalized before return)
    ev_id = "fse_" + uuid.uuid4().hex[:24]
    queued = {
        "id": ev_id,
        "account_id": account_id if isinstance(account_id, str) else "unknown",
        "tool_name": "get_ticket_fields",
        "request_params": {"account_id": account_id, "workspace_id": workspace_id} if isinstance(account_id, str) else {"workspace_id": workspace_id},
        "http_method": "GET",
        "endpoint": "/api/v2/ticket_fields",
        "status": "queued",
        "error_message": None,
        "affected_collection": "tickets",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    events.append(queued)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None, payload=None, affected_id=None):
        # update the queued event exactly once
        events2 = _load("integration_events.json")
        for e in events2:
            if e.get("id") == ev_id and e.get("status") == "queued":
                e["status"] = status
                e["error_message"] = error_message
                e["affected_id"] = affected_id
                dur = int(max(0, round((time.time() - t0) * 1000)))
                e["duration_ms"] = dur
                e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("integration_events.json", events2)
        return payload

    # Validation
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        return _finalize("failed", "Invalid account_id.", _err("VALIDATION_ERROR", "Invalid account_id."))
    if workspace_id is not None and not isinstance(workspace_id, int):
        return _finalize("failed", "Invalid workspace_id.", _err("VALIDATION_ERROR", "workspace_id must be an integer."))

    # Authorization: must map to exactly one active account row
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        return _finalize("failed", "Account not found.", _err("NOT_FOUND", "Account not found.", account_id=account_id))
    if acct.get("status") != "active":
        return _finalize("failed", "Account is not active.", _err("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status")))

    ws = workspace_id
    if ws is None:
        ws = acct.get("default_workspace_id")

    # If workspace_id is explicitly provided or default exists, validate it exists as a workspace entity
    if ws is not None:
        if not isinstance(ws, int):
            return _finalize("failed", "Invalid resolved workspace_id.", _err("VALIDATION_ERROR", "Resolved workspace_id must be an integer."))
        ws_row = next((r for r in catalog if r.get("account_id") == account_id and r.get("entity_type") == "workspace" and r.get("freshservice_id") == ws and r.get("status") != "deleted"), None)
        if not ws_row:
            return _finalize("failed", "Workspace not found.", _err("NOT_FOUND", "Workspace not found.", account_id=account_id, workspace_id=ws))

    # Fetch cached schema payload if present on any ticket rows for this account/workspace
    # Prefer a cache tied to the requested workspace; else any cache for the account.
    cache = None
    if ws is not None:
        for r in tickets:
            if r.get("account_id") == account_id and r.get("record_type") == "ticket" and r.get("workspace_id") == ws:
                c = r.get("ticket_fields_schema_cache")
                if isinstance(c, dict):
                    cache = c
                    break
    if cache is None:
        for r in tickets:
            if r.get("account_id") == account_id and r.get("record_type") == "ticket":
                c = r.get("ticket_fields_schema_cache")
                if isinstance(c, dict):
                    cache = c
                    break

    # If no cache exists, return an empty list (read tools return empty result, not error)
    fields = []
    if isinstance(cache, dict):
        # Accept either vendor-like {"ticket_fields":[...]} or {"fields":[...]} or direct list in {"data":[...]}
        if isinstance(cache.get("ticket_fields"), list):
            fields = cache.get("ticket_fields")
        elif isinstance(cache.get("fields"), list):
            fields = cache.get("fields")
        elif isinstance(cache.get("data"), list):
            fields = cache.get("data")
        elif isinstance(cache.get("results"), list):
            fields = cache.get("results")
        else:
            # If it's some other dict shape, return it as a single "raw" field collection
            fields = [cache]

    resp = {
        "account_id": account_id,
        "workspace_id": ws,
        "fields": fields,
        "count": len(fields)
    }
    return _finalize("succeeded", None, resp)

def get_tickets(account_id, workspace_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    events = _load("integration_events.json")
    accounts = _load("fs_accounts.json")
    tickets = _load("tickets.json")
    catalog = _load("catalog_and_kb.json")

    ev_id = "fse_" + uuid.uuid4().hex[:24]
    queued = {
        "id": ev_id,
        "account_id": account_id if isinstance(account_id, str) else "unknown",
        "tool_name": "get_tickets",
        "request_params": {
            "account_id": account_id,
            "workspace_id": workspace_id,
            "limit": limit,
            "cursor": cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        } if isinstance(account_id, str) else {},
        "http_method": "GET",
        "endpoint": "/api/v2/tickets",
        "status": "queued",
        "error_message": None,
        "affected_collection": "tickets",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    events.append(queued)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None, payload=None):
        events2 = _load("integration_events.json")
        for e in events2:
            if e.get("id") == ev_id and e.get("status") == "queued":
                e["status"] = status
                e["error_message"] = error_message
                e["duration_ms"] = int(max(0, round((time.time() - t0) * 1000)))
                e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("integration_events.json", events2)
        return payload

    # Validation
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        return _finalize("failed", "Invalid account_id.", _err("VALIDATION_ERROR", "Invalid account_id."))
    if workspace_id is not None and not isinstance(workspace_id, int):
        return _finalize("failed", "Invalid workspace_id.", _err("VALIDATION_ERROR", "workspace_id must be an integer."))
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _finalize("failed", "Invalid limit.", _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100."))
    if cursor is not None and not isinstance(cursor, str):
        return _finalize("failed", "Invalid cursor.", _err("VALIDATION_ERROR", "cursor must be a string."))
    if sort_by is None:
        sort_by = "updated_at"
    if sort_order is None:
        sort_order = "desc"
    if sort_by not in ("created_at", "updated_at"):
        return _finalize("failed", "Invalid sort_by.", _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at."))
    if sort_order not in ("asc", "desc"):
        return _finalize("failed", "Invalid sort_order.", _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc."))

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        return _finalize("failed", "Account not found.", _err("NOT_FOUND", "Account not found.", account_id=account_id))
    if acct.get("status") != "active":
        return _finalize("failed", "Account is not active.", _err("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status")))

    if workspace_id is not None:
        ws_row = next((r for r in catalog if r.get("account_id") == account_id and r.get("entity_type") == "workspace" and r.get("freshservice_id") == workspace_id and r.get("status") != "deleted"), None)
        if not ws_row:
            return _finalize("failed", "Workspace not found.", _err("NOT_FOUND", "Workspace not found.", account_id=account_id, workspace_id=workspace_id))

    # Cursor decode: base64url("offset:<n>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return _finalize("failed", "Invalid cursor.", _err("VALIDATION_ERROR", "Invalid cursor."))
            offset = int(s.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            return _finalize("failed", "Invalid cursor.", _err("VALIDATION_ERROR", "Invalid cursor."))

    # Filter
    rows = [r for r in tickets if r.get("account_id") == account_id and r.get("record_type") == "ticket"]
    if workspace_id is not None:
        rows = [r for r in rows if r.get("workspace_id") == workspace_id]

    def _dt_key(v):
        if not isinstance(v, str) or not v:
            return ""
        return v

    reverse = (sort_order == "desc")
    rows.sort(key=lambda r: _dt_key(r.get(sort_by)), reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        nxt = f"offset:{offset + limit}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(nxt).decode("utf-8").rstrip("=")

    resp = {
        "tickets": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    return _finalize("succeeded", None, resp)

def create_ticket(account_id, ticket, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    events = _load("integration_events.json")
    accounts = _load("fs_accounts.json")
    people = _load("people_and_groups.json")
    tickets = _load("tickets.json")
    catalog = _load("catalog_and_kb.json")

    ev_id = "fse_" + uuid.uuid4().hex[:24]
    queued = {
        "id": ev_id,
        "account_id": account_id if isinstance(account_id, str) else "unknown",
        "tool_name": "create_ticket",
        "request_params": {"account_id": account_id, "ticket": ticket} if isinstance(account_id, str) else {},
        "http_method": "POST",
        "endpoint": "/api/v2/tickets",
        "status": "queued",
        "error_message": None,
        "affected_collection": "tickets",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    events.append(queued)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None, payload=None, affected_id=None):
        events2 = _load("integration_events.json")
        for e in events2:
            if e.get("id") == ev_id and e.get("status") == "queued":
                e["status"] = status
                e["error_message"] = error_message
                e["affected_id"] = affected_id
                e["duration_ms"] = int(max(0, round((time.time() - t0) * 1000)))
                e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("integration_events.json", events2)
        return payload

    # Validation
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        return _finalize("failed", "Invalid account_id.", _err("VALIDATION_ERROR", "Invalid account_id."))
    if not isinstance(ticket, dict):
        return _finalize("failed", "Invalid ticket payload.", _err("VALIDATION_ERROR", "ticket must be an object."))

    subject = ticket.get("subject")
    description = ticket.get("description")
    if not isinstance(subject, str) or not subject.strip():
        return _finalize("failed", "Missing subject.", _err("VALIDATION_ERROR", "ticket.subject is required."))
    if not isinstance(description, str) or not description.strip():
        return _finalize("failed", "Missing description.", _err("VALIDATION_ERROR", "ticket.description is required."))

    for fld in ("workspace_id", "priority", "impact", "urgency"):
        if fld in ticket and ticket[fld] is not None and not isinstance(ticket[fld], int):
            return _finalize("failed", f"Invalid {fld}.", _err("VALIDATION_ERROR", f"ticket.{fld} must be an integer."))

    if "priority" in ticket and ticket["priority"] is not None:
        if ticket["priority"] < 1 or ticket["priority"] > 4:
            return _finalize("failed", "Invalid priority.", _err("VALIDATION_ERROR", "ticket.priority must be between 1 and 4."))

    for fld in ("requester_id", "agent_id", "group_id"):
        if fld in ticket and ticket[fld] is not None:
            if not isinstance(ticket[fld], str) or not re.match(r"^fsp_[A-Za-z0-9]+$", ticket[fld]):
                return _finalize("failed", f"Invalid {fld}.", _err("VALIDATION_ERROR", f"ticket.{fld} must match ^fsp_[A-Za-z0-9]+$."))

    if "tags" in ticket and ticket["tags"] is not None:
        if not isinstance(ticket["tags"], list) or any((not isinstance(x, str)) for x in ticket["tags"]):
            return _finalize("failed", "Invalid tags.", _err("VALIDATION_ERROR", "ticket.tags must be an array of strings."))

    if "custom_fields" in ticket and ticket["custom_fields"] is not None and not isinstance(ticket["custom_fields"], dict):
        return _finalize("failed", "Invalid custom_fields.", _err("VALIDATION_ERROR", "ticket.custom_fields must be an object."))

    for fld in ("category", "sub_category", "item_category"):
        if fld in ticket and ticket[fld] is not None and not isinstance(ticket[fld], str):
            return _finalize("failed", f"Invalid {fld}.", _err("VALIDATION_ERROR", f"ticket.{fld} must be a string."))

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        return _finalize("failed", "Account not found.", _err("NOT_FOUND", "Account not found.", account_id=account_id))
    if acct.get("status") != "active":
        return _finalize("failed", "Account is not active.", _err("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status")))

    ws = ticket.get("workspace_id")
    if ws is None:
        ws = acct.get("default_workspace_id")
    if ws is not None:
        ws_row = next((r for r in catalog if r.get("account_id") == account_id and r.get("entity_type") == "workspace" and r.get("freshservice_id") == ws and r.get("status") != "deleted"), None)
        if not ws_row:
            return _finalize("failed", "Workspace not found.", _err("NOT_FOUND", "Workspace not found.", account_id=account_id, workspace_id=ws))

    requester_id = ticket.get("requester_id")
    if requester_id is not None:
        req = next((p for p in people if p.get("id") == requester_id and p.get("account_id") == account_id and p.get("entity_type") == "requester" and p.get("status") != "deleted"), None)
        if not req:
            return _finalize("failed", "Requester not found.", _err("NOT_FOUND", "Requester not found.", account_id=account_id, requester_id=requester_id))

    agent_id = ticket.get("agent_id")
    if agent_id is not None:
        ag = next((p for p in people if p.get("id") == agent_id and p.get("account_id") == account_id and p.get("entity_type") == "agent" and p.get("status") != "deleted"), None)
        if not ag:
            return _finalize("failed", "Agent not found.", _err("NOT_FOUND", "Agent not found.", account_id=account_id, agent_id=agent_id))

    group_id = ticket.get("group_id")
    if group_id is not None:
        grp = next((p for p in people if p.get("id") == group_id and p.get("account_id") == account_id and p.get("entity_type") == "group" and p.get("status") != "deleted"), None)
        if not grp:
            return _finalize("failed", "Group not found.", _err("NOT_FOUND", "Group not found.", account_id=account_id, group_id=group_id))

    # Create
    new_id = "fst_" + uuid.uuid4().hex[:24]
    row = {
        "id": new_id,
        "account_id": account_id,
        "record_type": "ticket",
        "freshservice_id": None,
        "ticket_id": None,
        "workspace_id": ws,
        "requester_id": requester_id,
        "agent_id": agent_id,
        "group_id": group_id,
        "subject": subject,
        "description": description,
        "priority": ticket.get("priority"),
        "impact": ticket.get("impact"),
        "urgency": ticket.get("urgency"),
        "category": ticket.get("category"),
        "sub_category": ticket.get("sub_category"),
        "item_category": ticket.get("item_category"),
        "tags": ticket.get("tags"),
        "custom_fields": ticket.get("custom_fields"),
        "conversation_body": None,
        "conversation_type": None,
        "private": None,
        "from_email": None,
        "to_emails": None,
        "cc_emails": None,
        "requested_item_payload": None,
        "ticket_fields_schema_cache": None,
        "status": "open",
        "created_at": now,
        "updated_at": now
    }

    tickets.append(row)
    _save("tickets.json", tickets)

    return _finalize("succeeded", None, {"ticket": row}, affected_id=new_id)

def update_ticket(account_id, ticket_id, ticket, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    events = _load("integration_events.json")
    accounts = _load("fs_accounts.json")
    people = _load("people_and_groups.json")
    tickets = _load("tickets.json")
    catalog = _load("catalog_and_kb.json")

    ev_id = "fse_" + uuid.uuid4().hex[:24]
    queued = {
        "id": ev_id,
        "account_id": account_id if isinstance(account_id, str) else "unknown",
        "tool_name": "update_ticket",
        "request_params": {"account_id": account_id, "ticket_id": ticket_id, "ticket": ticket} if isinstance(account_id, str) else {},
        "http_method": "PUT",
        "endpoint": "/api/v2/tickets/{id}",
        "status": "queued",
        "error_message": None,
        "affected_collection": "tickets",
        "affected_id": ticket_id if isinstance(ticket_id, str) else None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    events.append(queued)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None, payload=None, affected_id=None):
        events2 = _load("integration_events.json")
        for e in events2:
            if e.get("id") == ev_id and e.get("status") == "queued":
                e["status"] = status
                e["error_message"] = error_message
                if affected_id is not None:
                    e["affected_id"] = affected_id
                e["duration_ms"] = int(max(0, round((time.time() - t0) * 1000)))
                e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("integration_events.json", events2)
        return payload

    # Validation
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        return _finalize("failed", "Invalid account_id.", _err("VALIDATION_ERROR", "Invalid account_id."))
    if not isinstance(ticket_id, str) or not re.match(r"^fst_[A-Za-z0-9]+$", ticket_id):
        return _finalize("failed", "Invalid ticket_id.", _err("VALIDATION_ERROR", "Invalid ticket_id."))
    if not isinstance(ticket, dict):
        return _finalize("failed", "Invalid ticket payload.", _err("VALIDATION_ERROR", "ticket must be an object."))

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        return _finalize("failed", "Account not found.", _err("NOT_FOUND", "Account not found.", account_id=account_id))
    if acct.get("status") != "active":
        return _finalize("failed", "Account is not active.", _err("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status")))

    row = next((r for r in tickets if r.get("id") == ticket_id and r.get("account_id") == account_id and r.get("record_type") == "ticket"), None)
    if not row:
        return _finalize("failed", "Ticket not found.", _err("NOT_FOUND", "Ticket not found.", account_id=account_id, ticket_id=ticket_id))
    if row.get("status") == "deleted":
        return _finalize("failed", "Ticket is deleted.", _err("INVALID_TRANSITION", "Cannot update a deleted ticket.", ticket_id=ticket_id, status=row.get("status")))

    # Field validations
    if "workspace_id" in ticket and ticket["workspace_id"] is not None and not isinstance(ticket["workspace_id"], int):
        return _finalize("failed", "Invalid workspace_id.", _err("VALIDATION_ERROR", "ticket.workspace_id must be an integer."))
    for fld in ("priority", "impact", "urgency"):
        if fld in ticket and ticket[fld] is not None and not isinstance(ticket[fld], int):
            return _finalize("failed", f"Invalid {fld}.", _err("VALIDATION_ERROR", f"ticket.{fld} must be an integer."))
    if "priority" in ticket and ticket["priority"] is not None:
        if ticket["priority"] < 1 or ticket["priority"] > 4:
            return _finalize("failed", "Invalid priority.", _err("VALIDATION_ERROR", "ticket.priority must be between 1 and 4."))

    for fld in ("requester_id", "agent_id", "group_id"):
        if fld in ticket and ticket[fld] is not None:
            if not isinstance(ticket[fld], str) or not re.match(r"^fsp_[A-Za-z0-9]+$", ticket[fld]):
                return _finalize("failed", f"Invalid {fld}.", _err("VALIDATION_ERROR", f"ticket.{fld} must match ^fsp_[A-Za-z0-9]+$."))

    if "tags" in ticket and ticket["tags"] is not None:
        if not isinstance(ticket["tags"], list) or any((not isinstance(x, str)) for x in ticket["tags"]):
            return _finalize("failed", "Invalid tags.", _err("VALIDATION_ERROR", "ticket.tags must be an array of strings."))

    if "custom_fields" in ticket and ticket["custom_fields"] is not None and not isinstance(ticket["custom_fields"], dict):
        return _finalize("failed", "Invalid custom_fields.", _err("VALIDATION_ERROR", "ticket.custom_fields must be an object."))

    for fld in ("subject", "description", "category", "sub_category", "item_category"):
        if fld in ticket and ticket[fld] is not None and not isinstance(ticket[fld], str):
            return _finalize("failed", f"Invalid {fld}.", _err("VALIDATION_ERROR", f"ticket.{fld} must be a string."))

    if "status" in ticket and ticket["status"] is not None:
        if ticket["status"] not in ("open", "pending", "resolved", "closed", "deleted", "active"):
            return _finalize("failed", "Invalid status.", _err("VALIDATION_ERROR", "Invalid ticket.status."))

    # Reference checks for any newly set ids
    if "workspace_id" in ticket:
        ws = ticket.get("workspace_id")
        if ws is None:
            ws = acct.get("default_workspace_id")
        if ws is not None:
            ws_row = next((r for r in catalog if r.get("account_id") == account_id and r.get("entity_type") == "workspace" and r.get("freshservice_id") == ws and r.get("status") != "deleted"), None)
            if not ws_row:
                return _finalize("failed", "Workspace not found.", _err("NOT_FOUND", "Workspace not found.", account_id=account_id, workspace_id=ws))

    if "requester_id" in ticket and ticket.get("requester_id") is not None:
        req_id = ticket.get("requester_id")
        req = next((p for p in people if p.get("id") == req_id and p.get("account_id") == account_id and p.get("entity_type") == "requester" and p.get("status") != "deleted"), None)
        if not req:
            return _finalize("failed", "Requester not found.", _err("NOT_FOUND", "Requester not found.", account_id=account_id, requester_id=req_id))

    if "agent_id" in ticket and ticket.get("agent_id") is not None:
        ag_id = ticket.get("agent_id")
        ag = next((p for p in people if p.get("id") == ag_id and p.get("account_id") == account_id and p.get("entity_type") == "agent" and p.get("status") != "deleted"), None)
        if not ag:
            return _finalize("failed", "Agent not found.", _err("NOT_FOUND", "Agent not found.", account_id=account_id, agent_id=ag_id))

    if "group_id" in ticket and ticket.get("group_id") is not None:
        g_id = ticket.get("group_id")
        grp = next((p for p in people if p.get("id") == g_id and p.get("account_id") == account_id and p.get("entity_type") == "group" and p.get("status") != "deleted"), None)
        if not grp:
            return _finalize("failed", "Group not found.", _err("NOT_FOUND", "Group not found.", account_id=account_id, group_id=g_id))

    # Apply updates + lifecycle transition enforcement
    transitions = {
        "open": ["pending", "resolved", "closed", "deleted"],
        "pending": ["open", "resolved", "closed", "deleted"],
        "resolved": ["open", "closed", "deleted"],
        "closed": ["open", "deleted"],
        "active": ["deleted"],
        "deleted": []
    }

    if "status" in ticket and ticket["status"] is not None:
        new_status = ticket["status"]
        old_status = row.get("status")
        if new_status != old_status:
            allowed = transitions.get(old_status, [])
            if new_status not in allowed:
                return _finalize(
                    "failed",
                    "Invalid status transition.",
                    _err("INVALID_TRANSITION", "Illegal ticket status transition.", from_status=old_status, to_status=new_status, ticket_id=ticket_id),
                    affected_id=ticket_id
                )
            row["status"] = new_status

    # Update mutable fields (record_type=ticket only)
    updatable = [
        "workspace_id", "requester_id", "agent_id", "group_id",
        "subject", "description",
        "priority", "impact", "urgency",
        "category", "sub_category", "item_category",
        "tags", "custom_fields"
    ]
    for k in updatable:
        if k in ticket:
            if k == "workspace_id":
                ws = ticket.get("workspace_id")
                if ws is None:
                    ws = acct.get("default_workspace_id")
                row["workspace_id"] = ws
            else:
                row[k] = ticket.get(k)

    row["updated_at"] = now

    # Persist back: ensure we actually matched and mutated
    changed = False
    for i, r in enumerate(tickets):
        if r.get("id") == ticket_id and r.get("account_id") == account_id and r.get("record_type") == "ticket":
            tickets[i] = row
            changed = True
            break
    if not changed:
        return _finalize("failed", "Ticket not found.", _err("NOT_FOUND", "Ticket not found.", account_id=account_id, ticket_id=ticket_id))

    _save("tickets.json", tickets)
    return _finalize("succeeded", None, {"ticket": row}, affected_id=ticket_id)

def filter_tickets(account_id, filters=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_event(events, ev):
        events.append(ev)
        _save("integration_events.json", events)

    def _finish_event(events, ev_id, status, duration_ms, **updates):
        for e in events:
            if e.get("id") == ev_id:
                if e.get("status") != "queued":
                    return
                e["status"] = status
                e["duration_ms"] = int(duration_ms) if duration_ms is not None else 0
                e["updated_at"] = now
                for k, v in updates.items():
                    e[k] = v
                _save("integration_events.json", events)
                return

    def _new_id(prefix):
        import random, string
        return prefix + "".join(random.choice(string.ascii_letters + string.digits) for _ in range(18))

    def _validate_cursor(cur):
        if cur is None:
            return (0, None)
        if not isinstance(cur, str):
            return (None, _err("VALIDATION_ERROR", "cursor must be a string"))
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj:
                return (None, _err("VALIDATION_ERROR", "cursor is invalid"))
            off = obj["offset"]
            if not isinstance(off, int) or off < 0:
                return (None, _err("VALIDATION_ERROR", "cursor offset is invalid"))
            return (off, None)
        except Exception:
            return (None, _err("VALIDATION_ERROR", "cursor is invalid"))

    def _make_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    events = _load("integration_events.json")
    fs_accounts = _load("fs_accounts.json")

    # Validate account_id
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        # No active account can be associated -> still log failed (rule)
        ev_id = _new_id("fse_")
        _append_event(events, {
            "id": ev_id,
            "account_id": account_id if isinstance(account_id, str) else "unknown",
            "tool_name": "filter_tickets",
            "request_params": {"account_id": account_id, "filters": filters, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
            "http_method": "GET",
            "endpoint": "/tickets/filter",
            "status": "queued",
            "error_message": None,
            "affected_collection": "tickets",
            "affected_id": None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now
        })
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="Invalid account_id")
        return _err("VALIDATION_ERROR", "account_id is malformed")

    # Resolve active account (must exist and be active)
    acct = next((a for a in fs_accounts if a.get("id") == account_id), None)
    ev_id = _new_id("fse_")
    _append_event(events, {
        "id": ev_id,
        "account_id": account_id,
        "tool_name": "filter_tickets",
        "request_params": {"account_id": account_id, "filters": filters, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
        "http_method": "GET",
        "endpoint": "/tickets/filter",
        "status": "queued",
        "error_message": None,
        "affected_collection": "tickets",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    })

    if not acct:
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="Account not found")
        return _err("NOT_FOUND", "Account not found", account_id=account_id)
    if acct.get("status") != "active":
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="Account is not active")
        return _err("UNAUTHORIZED", "Account is not active", account_id=account_id)

    # Validate other params
    if filters is None:
        filters = {}
    if not isinstance(filters, dict):
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="filters must be an object")
        return _err("VALIDATION_ERROR", "filters must be an object")

    allowed_filter_keys = {"workspace_id", "requester_id", "agent_id", "group_id", "status", "priority", "impact", "urgency",
                           "tags", "category", "sub_category", "item_category", "freshservice_id", "query"}
    for k in filters.keys():
        if k not in allowed_filter_keys:
            duration = (time.time() - t0) * 1000
            _finish_event(events, ev_id, "failed", duration, error_message=f"Invalid filter field: {k}")
            return _err("VALIDATION_ERROR", f"Invalid filter field: {k}", field=k)

    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="limit must be an integer between 1 and 100")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at"):
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="sort_by must be 'created_at' or 'updated_at'")
        return _err("VALIDATION_ERROR", "sort_by must be 'created_at' or 'updated_at'")

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="sort_order must be 'asc' or 'desc'")
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'")

    offset, cur_err = _validate_cursor(cursor)
    if cur_err:
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message=cur_err["error"]["message"])
        return cur_err

    # Validate referenced ids
    def _check_pid(val, field, allowed_entity_types=None):
        if val is None:
            return None
        if not isinstance(val, str) or not re.match(r"^fsp_[A-Za-z0-9]+$", val):
            return _err("VALIDATION_ERROR", f"{field} is malformed", field=field)
        # ensure exists and belongs to account
        rows = _load("people_and_groups.json")
        r = next((x for x in rows if x.get("id") == val and x.get("account_id") == account_id), None)
        if not r:
            return _err("NOT_FOUND", f"{field} not found", field=field, id=val)
        if allowed_entity_types and r.get("entity_type") not in allowed_entity_types:
            return _err("VALIDATION_ERROR", f"{field} must reference a {', '.join(allowed_entity_types)}", field=field, id=val)
        return None

    # workspace existence check (workspace is stored in catalog_and_kb entity_type='workspace' with freshservice_id=workspace_id)
    w_id = filters.get("workspace_id")
    if w_id is not None:
        if not isinstance(w_id, int):
            duration = (time.time() - t0) * 1000
            _finish_event(events, ev_id, "failed", duration, error_message="workspace_id must be an integer")
            return _err("VALIDATION_ERROR", "workspace_id must be an integer", field="workspace_id")
        cat = _load("catalog_and_kb.json")
        ws = next((x for x in cat if x.get("account_id") == account_id and x.get("entity_type") == "workspace" and x.get("freshservice_id") == w_id and x.get("status") != "deleted"), None)
        if not ws:
            duration = (time.time() - t0) * 1000
            _finish_event(events, ev_id, "failed", duration, error_message="Workspace not found")
            return _err("NOT_FOUND", "Workspace not found", workspace_id=w_id)

    for field, types in (("requester_id", {"requester"}), ("agent_id", {"agent"}), ("group_id", {"group"})):
        e = _check_pid(filters.get(field), field, types)
        if e:
            duration = (time.time() - t0) * 1000
            _finish_event(events, ev_id, "failed", duration, error_message=e["error"]["message"])
            return e

    st = filters.get("status")
    if st is not None:
        if st not in ("open", "pending", "resolved", "closed", "deleted", "active"):
            duration = (time.time() - t0) * 1000
            _finish_event(events, ev_id, "failed", duration, error_message="Invalid status filter")
            return _err("VALIDATION_ERROR", "Invalid status filter", field="status")

    for int_field in ("priority", "impact", "urgency", "freshservice_id"):
        v = filters.get(int_field)
        if v is not None and not isinstance(v, int):
            duration = (time.time() - t0) * 1000
            _finish_event(events, ev_id, "failed", duration, error_message=f"{int_field} must be an integer")
            return _err("VALIDATION_ERROR", f"{int_field} must be an integer", field=int_field)

    pr = filters.get("priority")
    if pr is not None and (pr < 1 or pr > 4):
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="priority must be between 1 and 4")
        return _err("VALIDATION_ERROR", "priority must be between 1 and 4", field="priority")

    tags = filters.get("tags")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
            duration = (time.time() - t0) * 1000
            _finish_event(events, ev_id, "failed", duration, error_message="tags must be an array of strings")
            return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")

    q = filters.get("query")
    if q is not None and not isinstance(q, str):
        duration = (time.time() - t0) * 1000
        _finish_event(events, ev_id, "failed", duration, error_message="query must be a string")
        return _err("VALIDATION_ERROR", "query must be a string", field="query")

    # Load tickets and filter
    tickets = _load("tickets.json")
    rows = [t for t in tickets if t.get("account_id") == account_id and t.get("record_type") == "ticket"]

    def _contains_all_tags(row_tags, wanted):
        if not wanted:
            return True
        if not isinstance(row_tags, list):
            return False
        s = set([x for x in row_tags if isinstance(x, str)])
        for w in wanted:
            if w not in s:
                return False
        return True

    def _text_match(row, query):
        if not query:
            return True
        query_l = query.strip().lower()
        if not query_l:
            return True
        subj = (row.get("subject") or "")
        desc = (row.get("description") or "")
        return (query_l in str(subj).lower()) or (query_l in str(desc).lower())

    # apply field filters
    if w_id is not None:
        rows = [r for r in rows if r.get("workspace_id") == w_id]
    if filters.get("requester_id") is not None:
        rid = filters["requester_id"]
        rows = [r for r in rows if r.get("requester_id") == rid]
    if filters.get("agent_id") is not None:
        aid = filters["agent_id"]
        rows = [r for r in rows if r.get("agent_id") == aid]
    if filters.get("group_id") is not None:
        gid = filters["group_id"]
        rows = [r for r in rows if r.get("group_id") == gid]
    if st is not None:
        rows = [r for r in rows if r.get("status") == st]
    for f in ("priority", "impact", "urgency", "freshservice_id"):
        v = filters.get(f)
        if v is not None:
            rows = [r for r in rows if r.get(f) == v]
    for f in ("category", "sub_category", "item_category"):
        v = filters.get(f)
        if v is not None:
            rows = [r for r in rows if r.get(f) == v]
    if tags is not None:
        rows = [r for r in rows if _contains_all_tags(r.get("tags"), tags)]
    if q is not None:
        rows = [r for r in rows if _text_match(r, q)]

    total = len(rows)

    # Sort
    def _dt_key(v):
        if v is None:
            return ""
        return str(v)

    reverse = (sort_order == "desc")
    rows.sort(key=lambda r: _dt_key(r.get(sort_by)), reverse=reverse)

    # Pagination by offset cursor
    start = offset
    if start > total:
        start = total
    page = rows[start:start + limit]
    next_off = start + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    duration = (time.time() - t0) * 1000
    _finish_event(events, ev_id, "succeeded", duration)

    return {
        "tickets": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "sort_by": sort_by,
        "sort_order": sort_order
    }

def get_requested_items(account_id, ticket_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    events = _load("integration_events.json")
    event_id = f"fse_{int(time.time()*1000)}_{os.getpid()}"
    queued_event = {
        "id": event_id,
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "get_requested_items",
        "request_params": {"account_id": account_id, "ticket_id": ticket_id, "limit": limit, "cursor": cursor},
        "http_method": "GET",
        "endpoint": "/tickets/{ticket_id}/requested_items",
        "status": "queued",
        "error_message": None,
        "affected_collection": "tickets",
        "affected_id": ticket_id if isinstance(ticket_id, str) else None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    events.append(queued_event)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None, affected_id=None, vendor_id=None):
        end = time.time()
        dur = int(round((end - t0) * 1000))
        if dur < 0:
            dur = 0
        evs = _load("integration_events.json")
        for ev in reversed(evs):
            if ev.get("id") == event_id:
                if ev.get("status") == "queued":
                    ev["status"] = status
                    ev["error_message"] = error_message
                    ev["duration_ms"] = dur
                    ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    if affected_id is not None:
                        ev["affected_collection"] = "tickets"
                        ev["affected_id"] = affected_id
                    if vendor_id is not None:
                        ev["vendor_freshservice_id"] = vendor_id
                break
        _save("integration_events.json", evs)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        _finalize("failed", "Invalid account_id")
        return _err("VALIDATION_ERROR", "account_id must match ^fsa_[A-Za-z0-9]+$")

    if not isinstance(ticket_id, str) or not re.match(r"^fst_[A-Za-z0-9]+$", ticket_id):
        _finalize("failed", "Invalid ticket_id")
        return _err("VALIDATION_ERROR", "ticket_id must match ^fst_[A-Za-z0-9]+$")

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            _finalize("failed", "Invalid limit type")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            _finalize("failed", "limit out of range")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_v = limit

    if cursor is not None and not isinstance(cursor, str):
        _finalize("failed", "Invalid cursor type")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Authenticate ambient: must map to exactly one active account row matching account_id
    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        _finalize("failed", "No active account for request", affected_id=ticket_id)
        return _err("UNAUTHORIZED", "No active Freshservice account available for this request")

    tickets = _load("tickets.json")
    parent = next(
        (
            t
            for t in tickets
            if t.get("id") == ticket_id
            and t.get("account_id") == account_id
            and t.get("record_type") == "ticket"
        ),
        None,
    )
    if not parent or parent.get("status") == "deleted":
        _finalize("failed", "Ticket not found", affected_id=ticket_id)
        return _err("NOT_FOUND", "Ticket not found for account", account_id=account_id, ticket_id=ticket_id)

    # Service-request-ness: we don't have an explicit flag; require at least one requested_item child to consider it.
    children = [
        r
        for r in tickets
        if r.get("account_id") == account_id
        and r.get("record_type") == "requested_item"
        and r.get("ticket_id") == ticket_id
        and r.get("status") != "deleted"
    ]
    children.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""))

    # Pagination by cursor = integer offset string
    offset = 0
    if cursor:
        if not re.match(r"^\d+$", cursor):
            _finalize("failed", "Invalid cursor value", affected_id=ticket_id)
            return _err("VALIDATION_ERROR", "cursor is invalid")
        offset = int(cursor)

    if offset < 0 or offset > len(children):
        _finalize("failed", "Cursor out of range", affected_id=ticket_id)
        return _err("VALIDATION_ERROR", "cursor out of range")

    page = children[offset : offset + limit_v]
    next_off = offset + len(page)
    has_more = next_off < len(children)
    next_cursor = str(next_off) if has_more else None

    _finalize("succeeded", None, affected_id=ticket_id, vendor_id=parent.get("freshservice_id"))
    return {
        "requested_items": page,
        "ticket": {"id": parent.get("id"), "freshservice_id": parent.get("freshservice_id")},
        "meta": {"total": len(children), "limit": limit_v, "has_more": has_more, "next_cursor": next_cursor},
    }

def create_service_request(
    account_id,
    workspace_id=None,
    requester_id=None,
    subject=None,
    description=None,
    priority=None,
    impact=None,
    urgency=None,
    category=None,
    sub_category=None,
    item_category=None,
    tags=None,
    custom_fields=None,
    requested_item_payload=None,
    **_extra,
):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_urlsafe(18).replace('-','').replace('_','')}"[:32]

    def _finalize_event(ev_id, statusv, error_message=None, affected_id=None, vendor_id=None, t0=None):
        events2 = _load("integration_events.json")
        for r in events2:
            if r.get("id") == ev_id and r.get("status") == "queued":
                r["status"] = statusv
                r["error_message"] = error_message
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000)) if isinstance(t0, (int, float)) else 0
                r["updated_at"] = _utcnow_z()
                if affected_id is not None:
                    r["affected_id"] = affected_id
                if vendor_id is not None:
                    r["vendor_freshservice_id"] = vendor_id
                break
        _save("integration_events.json", events2)

    t0 = time.time()
    now = _utcnow_z()

    params = {
        "account_id": account_id,
        "workspace_id": workspace_id,
        "requester_id": requester_id,
        "subject": subject,
        "description": description,
        "priority": priority,
        "impact": impact,
        "urgency": urgency,
        "category": category,
        "sub_category": sub_category,
        "item_category": item_category,
        "tags": tags,
        "custom_fields": custom_fields,
        "requested_item_payload": requested_item_payload,
    }

    ev_id = _new_id("fse")
    events = _load("integration_events.json")
    events.append(
        {
            "id": ev_id,
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "create_service_request",
            "request_params": params,
            "http_method": "POST",
            "endpoint": "/service_requests",
            "status": "queued",
            "error_message": None,
            "affected_collection": "tickets",
            "affected_id": None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
    )
    _save("integration_events.json", events)

    try:
        if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
            _finalize_event(ev_id, "failed", "Invalid account_id.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")

        if not isinstance(requester_id, str) or not re.match(r"^fsp_[A-Za-z0-9]+$", requester_id):
            _finalize_event(ev_id, "failed", "Invalid requester_id.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid requester_id.", field="requester_id")

        if not isinstance(subject, str) or not subject.strip():
            _finalize_event(ev_id, "failed", "subject is required.", t0=t0)
            return _err("VALIDATION_ERROR", "subject is required.", field="subject")

        if requested_item_payload is None or not isinstance(requested_item_payload, dict):
            _finalize_event(ev_id, "failed", "requested_item_payload must be an object.", t0=t0)
            return _err("VALIDATION_ERROR", "requested_item_payload must be an object.", field="requested_item_payload")

        if workspace_id is not None and not isinstance(workspace_id, int):
            _finalize_event(ev_id, "failed", "workspace_id must be an integer.", t0=t0)
            return _err("VALIDATION_ERROR", "workspace_id must be an integer.", field="workspace_id")

        for f, v in (("priority", priority), ("impact", impact), ("urgency", urgency)):
            if v is not None and not isinstance(v, int):
                _finalize_event(ev_id, "failed", f"{f} must be an integer.", t0=t0)
                return _err("VALIDATION_ERROR", f"{f} must be an integer.", field=f)
        if priority is not None and (priority < 1 or priority > 4):
            _finalize_event(ev_id, "failed", "priority must be between 1 and 4.", t0=t0)
            return _err("VALIDATION_ERROR", "priority must be between 1 and 4.", field="priority")

        if description is not None and not isinstance(description, str):
            _finalize_event(ev_id, "failed", "description must be a string.", t0=t0)
            return _err("VALIDATION_ERROR", "description must be a string.", field="description")

        if tags is not None:
            if not isinstance(tags, list) or any((not isinstance(x, str) for x in tags)):
                _finalize_event(ev_id, "failed", "tags must be an array of strings.", t0=t0)
                return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")

        if custom_fields is not None and not isinstance(custom_fields, dict):
            _finalize_event(ev_id, "failed", "custom_fields must be an object.", t0=t0)
            return _err("VALIDATION_ERROR", "custom_fields must be an object.", field="custom_fields")

        # Resolve account context: must be exactly one active fs_accounts row for this call
        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if not acct:
            _finalize_event(ev_id, "failed", "Account not found.", t0=t0)
            return _err("NOT_FOUND", "Account not found.", account_id=account_id)
        if acct.get("status") != "active":
            _finalize_event(ev_id, "failed", "Account is not active.", t0=t0)
            return _err("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status"))

        # requester must exist under account and be requester type and not deleted
        pag = _load("people_and_groups.json")
        requester = next((p for p in pag if p.get("id") == requester_id), None)
        if not requester:
            _finalize_event(ev_id, "failed", "Requester not found.", t0=t0)
            return _err("NOT_FOUND", "Requester not found.", requester_id=requester_id)
        if requester.get("account_id") != account_id:
            _finalize_event(ev_id, "failed", "Requester not found in account.", t0=t0)
            return _err("NOT_FOUND", "Requester not found in account.", requester_id=requester_id, account_id=account_id)
        if requester.get("entity_type") != "requester":
            _finalize_event(ev_id, "failed", "requester_id must refer to a requester.", t0=t0)
            return _err("VALIDATION_ERROR", "requester_id must refer to a requester.", field="requester_id")
        if requester.get("status") == "deleted":
            _finalize_event(ev_id, "failed", "Requester is deleted.", t0=t0)
            return _err("CONFLICT", "Requester is deleted and cannot be used.", requester_id=requester_id)

        # workspace: accept as-is; if omitted use account default when present
        effective_workspace_id = workspace_id
        if effective_workspace_id is None and isinstance(acct.get("default_workspace_id"), int):
            effective_workspace_id = acct.get("default_workspace_id")

        tickets = _load("tickets.json")

        # Create parent ticket
        ticket_row_id = _new_id("fst")
        while any(r.get("id") == ticket_row_id for r in tickets):
            ticket_row_id = _new_id("fst")

        # Choose an integer freshservice_id (vendor id) unique for (account_id, record_type, freshservice_id)
        used_vendor_ids = {r.get("freshservice_id") for r in tickets if r.get("account_id") == account_id and r.get("record_type") == "ticket" and isinstance(r.get("freshservice_id"), int)}
        vendor_ticket_id = max(used_vendor_ids) + 1 if used_vendor_ids else 1

        status0 = "open"
        ticket_row = {
            "id": ticket_row_id,
            "account_id": account_id,
            "record_type": "ticket",
            "freshservice_id": vendor_ticket_id,
            "ticket_id": None,
            "workspace_id": effective_workspace_id,
            "requester_id": requester_id,
            "agent_id": None,
            "group_id": None,
            "subject": subject,
            "description": description,
            "priority": priority,
            "impact": impact,
            "urgency": urgency,
            "category": category,
            "sub_category": sub_category,
            "item_category": item_category,
            "tags": tags,
            "custom_fields": custom_fields,
            "conversation_body": None,
            "conversation_type": None,
            "private": None,
            "from_email": None,
            "to_emails": None,
            "cc_emails": None,
            "requested_item_payload": None,
            "ticket_fields_schema_cache": None,
            "status": status0,
            "created_at": now,
            "updated_at": now,
        }

        # Validate uniqueness for ticket vendor id
        if any(
            r.get("account_id") == account_id
            and r.get("record_type") == "ticket"
            and r.get("freshservice_id") == vendor_ticket_id
            for r in tickets
        ):
            _finalize_event(ev_id, "failed", "Ticket vendor id conflict.", t0=t0)
            return _err("CONFLICT", "Ticket vendor id conflict (please retry).")

        tickets.append(ticket_row)

        # Create one or more requested_item child rows. If payload contains list under "items", create multiple.
        def _as_items(payload):
            if isinstance(payload, dict) and isinstance(payload.get("items"), list) and payload.get("items"):
                items = []
                for it in payload.get("items"):
                    if isinstance(it, dict):
                        items.append(it)
                    else:
                        items.append({"value": it})
                return items
            return [payload]

        items = _as_items(requested_item_payload)

        # choose base vendor id for requested items
        used_req_ids = {r.get("freshservice_id") for r in tickets if r.get("account_id") == account_id and r.get("record_type") == "requested_item" and isinstance(r.get("freshservice_id"), int)}
        next_req_vendor = (max(used_req_ids) + 1) if used_req_ids else 1

        created_child_ids = []
        for it in items:
            child_id = _new_id("fst")
            while any(r.get("id") == child_id for r in tickets):
                child_id = _new_id("fst")
            # ensure vendor uniqueness
            while any(
                r.get("account_id") == account_id and r.get("record_type") == "requested_item" and r.get("freshservice_id") == next_req_vendor
                for r in tickets
            ):
                next_req_vendor += 1

            child_row = {
                "id": child_id,
                "account_id": account_id,
                "record_type": "requested_item",
                "freshservice_id": next_req_vendor,
                "ticket_id": ticket_row_id,
                "workspace_id": effective_workspace_id,
                "requester_id": requester_id,
                "agent_id": None,
                "group_id": None,
                "subject": None,
                "description": None,
                "priority": None,
                "impact": None,
                "urgency": None,
                "category": None,
                "sub_category": None,
                "item_category": None,
                "tags": None,
                "custom_fields": None,
                "conversation_body": None,
                "conversation_type": None,
                "private": None,
                "from_email": None,
                "to_emails": None,
                "cc_emails": None,
                "requested_item_payload": it,
                "ticket_fields_schema_cache": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            tickets.append(child_row)
            created_child_ids.append(child_id)
            next_req_vendor += 1

        _save("tickets.json", tickets)
        _finalize_event(ev_id, "succeeded", affected_id=ticket_row_id, vendor_id=vendor_ticket_id, t0=t0)

        return {"ticket": ticket_row, "requested_items": [r for r in tickets if r.get("id") in created_child_ids]}
    except Exception as e:
        _finalize_event(ev_id, "failed", f"Unexpected error: {type(e).__name__}", t0=t0)
        return _err("CONFLICT", "Unexpected error occurred.", detail=f"{type(e).__name__}")

def send_ticket_reply(account_id, ticket_id, conversation_body, from_email=None, to_emails=None, cc_emails=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    events = _load("integration_events.json")
    event_id = f"fse_{int(time.time()*1000)}_{os.getpid()}"
    queued_event = {
        "id": event_id,
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "send_ticket_reply",
        "request_params": {
            "account_id": account_id,
            "ticket_id": ticket_id,
            "conversation_body": conversation_body,
            "from_email": from_email,
            "to_emails": to_emails,
            "cc_emails": cc_emails,
        },
        "http_method": "POST",
        "endpoint": "/tickets/{ticket_id}/reply",
        "status": "queued",
        "error_message": None,
        "affected_collection": "tickets",
        "affected_id": ticket_id if isinstance(ticket_id, str) else None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    events.append(queued_event)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None, affected_id=None, vendor_id=None):
        end = time.time()
        dur = int(round((end - t0) * 1000))
        if dur < 0:
            dur = 0
        evs = _load("integration_events.json")
        for ev in reversed(evs):
            if ev.get("id") == event_id:
                if ev.get("status") == "queued":
                    ev["status"] = status
                    ev["error_message"] = error_message
                    ev["duration_ms"] = dur
                    ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    if affected_id is not None:
                        ev["affected_collection"] = "tickets"
                        ev["affected_id"] = affected_id
                    if vendor_id is not None:
                        ev["vendor_freshservice_id"] = vendor_id
                break
        _save("integration_events.json", evs)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        _finalize("failed", "Invalid account_id")
        return _err("VALIDATION_ERROR", "account_id must match ^fsa_[A-Za-z0-9]+$")

    if not isinstance(ticket_id, str) or not re.match(r"^fst_[A-Za-z0-9]+$", ticket_id):
        _finalize("failed", "Invalid ticket_id")
        return _err("VALIDATION_ERROR", "ticket_id must match ^fst_[A-Za-z0-9]+$")

    if not isinstance(conversation_body, str) or not conversation_body.strip():
        _finalize("failed", "Missing/empty conversation_body", affected_id=ticket_id)
        return _err("VALIDATION_ERROR", "conversation_body is required and must be a non-empty string")

    if from_email is not None and not isinstance(from_email, str):
        _finalize("failed", "Invalid from_email", affected_id=ticket_id)
        return _err("VALIDATION_ERROR", "from_email must be a string")

    def _validate_email_list(name, v):
        if v is None:
            return None
        if not isinstance(v, list) or any(not isinstance(x, str) for x in v):
            return _err("VALIDATION_ERROR", f"{name} must be an array of strings")
        return None

    e = _validate_email_list("to_emails", to_emails)
    if e:
        _finalize("failed", e["error"]["message"], affected_id=ticket_id)
        return e
    e = _validate_email_list("cc_emails", cc_emails)
    if e:
        _finalize("failed", e["error"]["message"], affected_id=ticket_id)
        return e

    # Auth: active account row required
    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        _finalize("failed", "No active account for request", affected_id=ticket_id)
        return _err("UNAUTHORIZED", "No active Freshservice account available for this request")

    tickets = _load("tickets.json")
    parent = next(
        (
            t
            for t in tickets
            if t.get("id") == ticket_id
            and t.get("account_id") == account_id
            and t.get("record_type") == "ticket"
        ),
        None,
    )
    if not parent:
        _finalize("failed", "Ticket not found", affected_id=ticket_id)
        return _err("NOT_FOUND", "Ticket not found for account", account_id=account_id, ticket_id=ticket_id)

    if parent.get("status") == "deleted":
        _finalize("failed", "Ticket deleted", affected_id=ticket_id, vendor_id=parent.get("freshservice_id"))
        return _err("CONFLICT", "Cannot add a reply to a deleted ticket", ticket_id=ticket_id)

    # Create conversation row
    def _new_id(prefix):
        return f"{prefix}{int(time.time()*1000)}{random.randint(1000,9999)}"

    existing_vendor_ids = [t.get("freshservice_id") for t in tickets if isinstance(t.get("freshservice_id"), int)]
    next_vendor_id = (max(existing_vendor_ids) + 1) if existing_vendor_ids else 1

    conv_id = "fst_" + _new_id("")
    conv_row = {
        "id": conv_id,
        "account_id": account_id,
        "record_type": "conversation",
        "freshservice_id": next_vendor_id,
        "ticket_id": ticket_id,
        "workspace_id": parent.get("workspace_id"),
        "requester_id": parent.get("requester_id"),
        "agent_id": parent.get("agent_id"),
        "group_id": parent.get("group_id"),
        "subject": None,
        "description": None,
        "priority": None,
        "impact": None,
        "urgency": None,
        "category": None,
        "sub_category": None,
        "item_category": None,
        "tags": None,
        "custom_fields": None,
        "conversation_body": conversation_body,
        "conversation_type": "reply",
        "private": False,
        "from_email": from_email,
        "to_emails": to_emails,
        "cc_emails": cc_emails,
        "requested_item_payload": None,
        "ticket_fields_schema_cache": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Uniqueness on (account_id, record_type, freshservice_id)
    used = {(t.get("account_id"), t.get("record_type"), t.get("freshservice_id")) for t in tickets if t.get("freshservice_id") is not None}
    key = (account_id, "conversation", next_vendor_id)
    if key in used:
        _finalize("failed", "Uniqueness conflict on freshservice_id", affected_id=ticket_id, vendor_id=parent.get("freshservice_id"))
        return _err("CONFLICT", "Duplicate Freshservice object id would be created", key={"account_id": key[0], "record_type": key[1], "freshservice_id": key[2]})

    tickets.append(conv_row)
    # Touch parent updated_at
    parent["updated_at"] = now
    _save("tickets.json", tickets)

    _finalize("succeeded", None, affected_id=conv_id, vendor_id=next_vendor_id)
    return {"conversation": conv_row}

