            return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
        if not isinstance(ticket_id, str) or not re.match(r"^fst_[A-Za-z0-9]+$", ticket_id):
            _finalize_event(ev_id, "failed", "Invalid ticket_id.", t0=t0)
