        if not isinstance(conversation_body, str) or not conversation_body.strip():
            _finalize_event(ev_id, "failed", "conversation_body is required.", t0=t0)
            return _err("VALIDATION_ERROR", "conversation_body is required.", field="conversation_body")
        if private is not None and not isinstance(private, bool):
            _finalize_event(ev_id, "failed", "private must be boolean.", t0=t0)
            return _err("VALIDATION_ERROR", "private must be boolean.", field="private")

        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if not acct:
            _finalize_event(ev_id, "failed", "Account not found.", t0=t0)
            return _err("NOT_FOUND", "Account not found.", account_id=account_id)
        if acct.get("status") != "active":
            _finalize_event(ev_id, "failed", "Account is not active.", t0=t0)
            return _err("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status"))

        tickets = _load("tickets.json")
        parent = next((r for r in tickets if r.get("id") == ticket_id and r.get("record_type") == "ticket" and r.get("account_id") == account_id), None)
        if not parent:
            _finalize_event(ev_id, "failed", "Ticket not found.", t0=t0)
            return _err("NOT_FOUND", "Ticket not found.", account_id=account_id, ticket_id=ticket_id)
        if parent.get("status") == "deleted":
            _finalize_event(ev_id, "failed", "Cannot add note to deleted ticket.", t0=t0)
            return _err("CONFLICT", "Cannot add note to deleted ticket.", ticket_id=ticket_id)

        # Create note row
        note_id = _new_id("fst")
        while any(r.get("id") == note_id for r in tickets):
            note_id = _new_id("fst")

        used_vendor_ids = {r.get("freshservice_id") for r in tickets if r.get("account_id") == account_id and r.get("record_type") == "note" and isinstance(r.get("freshservice_id"), int)}
        vendor_note_id = max(used_vendor_ids) + 1 if used_vendor_ids else 1

        if any(r.get("account_id") == account_id and r.get("record_type") == "note" and r.get("freshservice_id") == vendor_note_id for r in tickets):
            _finalize_event(ev_id, "failed", "Note vendor id conflict.", t0=t0)
            return _err("CONFLICT", "Note vendor id conflict (please retry).")

        note_row = {
            "id": note_id,
            "account_id": account_id,
            "record_type": "note",
            "freshservice_id": vendor_note_id,
            "ticket_id": ticket_id,
            "workspace_id": parent.get("workspace_id"),
            "requester_id": parent.get("requester_id"),
            "agent_id": parent.get("agent_id"),
            "group_id": parent.get("group_id"),
            "subject": None,
            "description": None,
            "priority": None,
            "impact": None,
            "urgency": None,
            "category": None,
            "sub_category": None,
            "item_category": None,
            "tags": None,
            "custom_fields": None,
            "conversation_body": conversation_body,
            "conversation_type": "note",
            "private": bool(private) if private is not None else None,
            "from_email": None,
            "to_emails": None,
            "cc_emails": None,
            "requested_item_payload": None,
            "ticket_fields_schema_cache": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }

        tickets.append(note_row)
        _save("tickets.json", tickets)
        _finalize_event(ev_id, "succeeded", affected_id=note_id, vendor_id=vendor_note_id, t0=t0)
        return {"conversation": note_row}
    except Exception as e:
        _finalize_event(ev_id, "failed", f"Unexpected error: {type(e).__name__}", t0=t0)
        return _err("CONFLICT", "Unexpected error occurred.", detail=f"{type(e).__name__}")

