        }

    def _finalize_event(idx, status, error_message=None, affected_id=None, vendor_freshservice_id=None):
        dt_ms = int(max(0, (time.time() - t0) * 1000))
        events[idx]["status"] = status
        events[idx]["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        events[idx]["duration_ms"] = dt_ms
        if error_message is not None:
            events[idx]["error_message"] = error_message
        if affected_id is not None:
            events[idx]["affected_id"] = affected_id
            events[idx]["affected_collection"] = "tickets"
        if vendor_freshservice_id is not None:
            events[idx]["vendor_freshservice_id"] = vendor_freshservice_id
        _save("integration_events.json", events)

    # enqueue event
    events.append(_event_base("queued"))
    ev_idx = len(events) - 1
    _save("integration_events.json", events)

    # Validate inputs
    if not (isinstance(account_id, str) and re.match(r"^fsa_[A-Za-z0-9]+$", account_id)):
