    if private is not None and not isinstance(private, bool):
        _finalize_event(ev_idx, "failed", "Invalid private; must be boolean.")
        return _err("VALIDATION_ERROR", "Invalid private; must be boolean.", field="private")

    # Authenticate ambient: must have active fs_account matching account_id
    accounts = _load("fs_accounts.json")
    acc = next((a for a in accounts if a.get("id") == account_id), None)
    if not acc:
