    if sort is None:
        sort = "-created_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at"):
        _finalize_event(ev_idx, "failed", "Invalid sort.")
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")
    if cursor is not None and not isinstance(cursor, str):
        _finalize_event(ev_idx, "failed", "Invalid cursor.")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    accounts = _load("fs_accounts.json")
    acc = next((a for a in accounts if a.get("id") == account_id), None)
    if not acc:
        _finalize_event(ev_idx, "failed", "Account not found.")
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    if acc.get("status") != "active":
        _finalize_event(ev_idx, "failed", "No active account available for this request.")
        return _err("UNAUTHORIZED", "No active account available for this request.", account_id=account_id)

    tickets = _load("tickets.json")
    parent = next((r for r in tickets if r.get("id") == ticket_id and r.get("account_id") == account_id), None)
    if not parent or parent.get("record_type") != "ticket":
        _finalize_event(ev_idx, "failed", "Ticket not found under this account.")
        return _err("NOT_FOUND", "Ticket not found.", ticket_id=ticket_id)
    if parent.get("status") == "deleted":
        _finalize_event(ev_idx, "failed", "Ticket is deleted.")
        return _err("NOT_FOUND", "Ticket not found.", ticket_id=ticket_id)

    # Cursor decoding
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            payload = json.loads(raw)
            if payload.get("ticket_id") != ticket_id:
                _finalize_event(ev_idx, "failed", "Cursor does not match ticket.")
                return _err("VALIDATION_ERROR", "Cursor does not match ticket.", field="cursor")
            start = int(payload.get("offset", 0))
            if start < 0:
                raise ValueError("offset<0")
        except Exception:
            _finalize_event(ev_idx, "failed", "Invalid cursor.")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    rows = [
        r for r in tickets
        if r.get("account_id") == account_id
        and r.get("ticket_id") == ticket_id
        and r.get("record_type") in ("conversation", "note")
        and r.get("status") != "deleted"
    ]

    if conversation_type is not None:
        # notes have conversation_type='note' potentially; for record_type='note' we treat as note
        def _ctype(r):
            if r.get("record_type") == "note":
                return "note"
            return r.get("conversation_type")
        rows = [r for r in rows if _ctype(r) == conversation_type]

    if private is not None:
        rows = [r for r in rows if bool(r.get("private", False)) == private]

    # Sorting
    key_field = sort.lstrip("-")
    reverse = sort.startswith("-")
    def _key(r):
        v = r.get(key_field)
        return (v is None, v)
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        payload = {"ticket_id": ticket_id, "offset": start + limit, "sort": sort, "limit": limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    _finalize_event(ev_idx, "succeeded", affected_id=ticket_id, vendor_freshservice_id=parent.get("freshservice_id"))

    return {
        "conversations": page,
        "meta": {
            "account_id": account_id,
            "ticket_id": ticket_id,
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "cursor": cursor
        }
    }

