            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    events = _load("integration_events.json")
    event_id = f"ev_{int(time.time()*1000)}_{os.getpid()}"
    def _event_base(status):
        return {
            "id": event_id,
            "account_id": account_id if isinstance(account_id, str) else "",
            "tool_name": "get_products_by_id",
            "request_params": {"account_id": account_id, "product_id": product_id},
            "http_method": "GET",
            "endpoint": "/products/{product_id}",
            "status": status,
            "error_message": None,
            "affected_collection": "catalog_and_kb",
            "affected_id": product_id if isinstance(product_id, str) else None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }

    def _finalize_event(idx, status, error_message=None, vendor_freshservice_id=None):
        dt_ms = int(max(0, (time.time() - t0) * 1000))
        events[idx]["status"] = status
        events[idx]["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        events[idx]["duration_ms"] = dt_ms
        if error_message is not None:
            events[idx]["error_message"] = error_message
        if vendor_freshservice_id is not None:
            events[idx]["vendor_freshservice_id"] = vendor_freshservice_id
        _save("integration_events.json", events)

    # enqueue
    events.append(_event_base("queued"))
    ev_idx = len(events) - 1
    _save("integration_events.json", events)

    # Validate
    if not (isinstance(account_id, str) and re.match(r"^fsa_[A-Za-z0-9]+$", account_id)):
        _finalize_event(ev_idx, "failed", "Invalid account_id.")
        return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
    if not (isinstance(product_id, str) and re.match(r"^fsx_[A-Za-z0-9]+$", product_id)):
        _finalize_event(ev_idx, "failed", "Invalid product_id.")
        return _err("VALIDATION_ERROR", "Invalid product_id.", field="product_id")

    accounts = _load("fs_accounts.json")
    acc = next((a for a in accounts if a.get("id") == account_id), None)
    if not acc:
        _finalize_event(ev_idx, "failed", "Account not found.")
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    if acc.get("status") != "active":
        _finalize_event(ev_idx, "failed", "No active account available for this request.")
        return _err("UNAUTHORIZED", "No active account available for this request.", account_id=account_id)

    rows = _load("catalog_and_kb.json")
    prod = next((r for r in rows if r.get("id") == product_id and r.get("account_id") == account_id and r.get("entity_type") == "product"), None)
    if not prod:
        _finalize_event(ev_idx, "failed", "Product not found under this account.")
        return _err("NOT_FOUND", "Product not found.", product_id=product_id)

    _finalize_event(ev_idx, "succeeded", vendor_freshservice_id=prod.get("freshservice_id"))

    return {"product": prod, "meta": {"account_id": account_id}}

