    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(8).upper()}"

    def _record_event(events, acc_id, status, tool_name, params, affected_collection=None, affected_id=None, vendor_freshservice_id=None, error_message=None, http_method=None, endpoint=None):
        now = _now()
        ev = {
            "id": _new_id("evt"),
            "account_id": acc_id,
            "tool_name": tool_name,
            "request_params": params if isinstance(params, dict) else {},
            "http_method": http_method,
            "endpoint": endpoint,
            "status": "queued",
            "error_message": None,
            "affected_collection": affected_collection,
            "affected_id": affected_id,
            "vendor_freshservice_id": vendor_freshservice_id,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        ev["status"] = status
        ev["error_message"] = error_message
        ev["duration_ms"] = max(0, int((time.time() - _t0) * 1000))
        ev["updated_at"] = _now()
        return ev

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]+$", account_id):
        return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "Product name is required.", field="name")
    if workspace_id is not None and not isinstance(workspace_id, int):
        return _err("VALIDATION_ERROR", "workspace_id must be an integer.", field="workspace_id")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")

    accounts = _load("fs_accounts.json")
    catalog = _load("catalog_and_kb.json")
    events = _load("integration_events.json")

    # Resolve account context: must exist and be active
    acc = next((a for a in accounts if a.get("id") == account_id), None)
    if not acc:
        _record_event(events, account_id, "failed", "create_product", {"account_id": account_id, "workspace_id": workspace_id, "name": name, "description": description},
                      affected_collection="catalog_and_kb", error_message="Account not found.")
        _save("integration_events.json", events)
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    if acc.get("status") != "active":
        _record_event(events, account_id, "failed", "create_product", {"account_id": account_id, "workspace_id": workspace_id, "name": name, "description": description},
                      affected_collection="catalog_and_kb", error_message="Account is not active.")
        _save("integration_events.json", events)
        return _err("UNAUTHORIZED", "Account is not active.", account_id=account_id)

    # Validate workspace_id exists for account when provided
    if workspace_id is not None:
        ws_ok = any(r.get("account_id") == account_id and r.get("entity_type") == "workspace" and r.get("freshservice_id") == workspace_id and r.get("status") != "deleted"
                    for r in catalog)
        if not ws_ok:
            _record_event(events, account_id, "failed", "create_product", {"account_id": account_id, "workspace_id": workspace_id, "name": name, "description": description},
                          affected_collection="catalog_and_kb", error_message="workspace_id not found for account.")
            _save("integration_events.json", events)
            return _err("VALIDATION_ERROR", "workspace_id is not valid for this account.", field="workspace_id", workspace_id=workspace_id)

    # Conflict detection: prevent same name in same workspace context
    norm_name = name.strip().lower()
    for r in catalog:
        if r.get("account_id") != account_id or r.get("entity_type") != "product":
            continue
        if r.get("status") == "deleted":
            continue
        if isinstance(r.get("name"), str) and r.get("name").strip().lower() == norm_name and r.get("workspace_id") == workspace_id:
            _record_event(events, account_id, "failed", "create_product", {"account_id": account_id, "workspace_id": workspace_id, "name": name, "description": description},
                          affected_collection="catalog_and_kb", affected_id=r.get("id"), vendor_freshservice_id=r.get("freshservice_id"),
                          error_message="Product with same name already exists.")
            _save("integration_events.json", events)
            return _err("CONFLICT", "A product with the same name already exists in this workspace.", name=name.strip(), workspace_id=workspace_id)

    # Create product replica (no vendor id yet; keep freshservice_id required in schema? For products freshservice_id is non-null.
    # Real replica should have a vendor id; but offline server must not fabricate vendor objects. We generate a unique negative placeholder? Not allowed.
    # Instead: require that vendor id be present? Tool doesn't accept it. We'll generate a stable local vendor_freshservice_id surrogate in allowed type (integer) without claiming it's vendor.
    # Use a monotonically decreasing negative id per account to avoid collision; still integer and unique.
    used_ids = {r.get("freshservice_id") for r in catalog if r.get("account_id") == account_id and r.get("entity_type") == "product" and isinstance(r.get("freshservice_id"), int)}
    fs_id = -1
    while fs_id in used_ids:
        fs_id -= 1

    now = _now()
    prod = {
        "id": _new_id("fsx"),
        "account_id": account_id,
        "entity_type": "product",
        "freshservice_id": fs_id,
        "parent_id": None,
        "workspace_id": workspace_id,
        "name": name.strip(),
        "description": description,
        "body": None,
        "tags": None,
        "visibility": None,
        "draft": None,
        "published_at": None,
        "raw_payload": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    catalog.append(prod)
    _save("catalog_and_kb.json", catalog)

    _record_event(events, account_id, "succeeded", "create_product", {"account_id": account_id, "workspace_id": workspace_id, "name": name, "description": description},
                  affected_collection="catalog_and_kb", affected_id=prod["id"], vendor_freshservice_id=prod["freshservice_id"])
    _save("integration_events.json", events)

    return {"product": prod}

