            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        ev["status"] = status2
        ev["error_message"] = error_message
        ev["duration_ms"] = max(0, int((time.time() - _t0) * 1000))
        ev["updated_at"] = _now()
        return ev

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]+$", account_id):
        return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
    if not isinstance(product_id, str) or not re.match(r"^fsx_[0-9A-Z]+$", product_id):
        return _err("VALIDATION_ERROR", "Invalid product_id.", field="product_id")
    if workspace_id is not None and not isinstance(workspace_id, int):
        return _err("VALIDATION_ERROR", "workspace_id must be an integer.", field="workspace_id")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if status is not None:
        allowed = {"active", "archived", "deleted", "draft", "published"}
        if not isinstance(status, str) or status not in allowed:
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(list(allowed)))

    accounts = _load("fs_accounts.json")
    catalog = _load("catalog_and_kb.json")
