        return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    if acc.get("status") != "active":
        _record_event(events, account_id, "failed", "update_product", {"account_id": account_id, "product_id": product_id, "workspace_id": workspace_id, "name": name, "description": description, "status": status},
                      affected_collection="catalog_and_kb", affected_id=product_id, error_message="Account is not active.")
        _save("integration_events.json", events)
        return _err("UNAUTHORIZED", "Account is not active.", account_id=account_id)

    prod = next((r for r in catalog if r.get("id") == product_id and r.get("account_id") == account_id and r.get("entity_type") == "product"), None)
    if not prod:
        _record_event(events, account_id, "failed", "update_product", {"account_id": account_id, "product_id": product_id, "workspace_id": workspace_id, "name": name, "description": description, "status": status},
                      affected_collection="catalog_and_kb", affected_id=product_id, error_message="Product not found.")
        _save("integration_events.json", events)
        return _err("NOT_FOUND", "Product not found for this account.", product_id=product_id)

    # Validate workspace belongs to account when updating
    if workspace_id is not None:
        ws_ok = any(r.get("account_id") == account_id and r.get("entity_type") == "workspace" and r.get("freshservice_id") == workspace_id and r.get("status") != "deleted"
                    for r in catalog)
        if not ws_ok:
            _record_event(events, account_id, "failed", "update_product", {"account_id": account_id, "product_id": product_id, "workspace_id": workspace_id, "name": name, "description": description, "status": status},
                          affected_collection="catalog_and_kb", affected_id=product_id, vendor_freshservice_id=prod.get("freshservice_id"),
                          error_message="workspace_id not found for account.")
            _save("integration_events.json", events)
            return _err("VALIDATION_ERROR", "workspace_id is not valid for this account.", field="workspace_id", workspace_id=workspace_id)

    # Status transition enforcement if provided
    if status is not None:
        cur = prod.get("status")
        transitions = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "draft": {"published", "deleted"},
            "published": {"draft", "deleted"},
            "deleted": set(),
        }
        if cur not in transitions:
            _record_event(events, account_id, "failed", "update_product", {"account_id": account_id, "product_id": product_id, "workspace_id": workspace_id, "name": name, "description": description, "status": status},
                          affected_collection="catalog_and_kb", affected_id=product_id, vendor_freshservice_id=prod.get("freshservice_id"),
                          error_message="Invalid current status.")
            _save("integration_events.json", events)
            return _err("CONFLICT", "Invalid current product status.", current_status=cur)
        if status != cur and status not in transitions[cur]:
            _record_event(events, account_id, "failed", "update_product", {"account_id": account_id, "product_id": product_id, "workspace_id": workspace_id, "name": name, "description": description, "status": status},
                          affected_collection="catalog_and_kb", affected_id=product_id, vendor_freshservice_id=prod.get("freshservice_id"),
                          error_message="Illegal status transition.")
            _save("integration_events.json", events)
            return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)

    # Uniqueness / conflict on name within same workspace context (when name or workspace changes)
    new_name = prod.get("name")
    if name is not None:
        new_name = name.strip()
    new_ws = prod.get("workspace_id")
    if workspace_id is not None:
        new_ws = workspace_id

    if new_name is not None:
        norm_name = new_name.strip().lower()
        for r in catalog:
            if r.get("id") == prod.get("id"):
                continue
            if r.get("account_id") != account_id or r.get("entity_type") != "product":
                continue
            if r.get("status") == "deleted":
                continue
            if isinstance(r.get("name"), str) and r.get("name").strip().lower() == norm_name and r.get("workspace_id") == new_ws:
                _record_event(events, account_id, "failed", "update_product", {"account_id": account_id, "product_id": product_id, "workspace_id": workspace_id, "name": name, "description": description, "status": status},
                              affected_collection="catalog_and_kb", affected_id=product_id, vendor_freshservice_id=prod.get("freshservice_id"),
                              error_message="Product with same name already exists.")
                _save("integration_events.json", events)
                return _err("CONFLICT", "A product with the same name already exists in this workspace.", name=new_name, workspace_id=new_ws)

    # Apply updates
    changed = False
    if workspace_id is not None and prod.get("workspace_id") != workspace_id:
        prod["workspace_id"] = workspace_id
        changed = True
    if name is not None and prod.get("name") != name.strip():
        prod["name"] = name.strip()
        changed = True
    if description is not None and prod.get("description") != description:
        prod["description"] = description
        changed = True
    if status is not None and prod.get("status") != status:
        prod["status"] = status
        changed = True

    if not changed:
        # Idempotent update: still succeed but must have matched a row (it did).
        _record_event(events, account_id, "succeeded", "update_product", {"account_id": account_id, "product_id": product_id, "workspace_id": workspace_id, "name": name, "description": description, "status": status},
                      affected_collection="catalog_and_kb", affected_id=product_id, vendor_freshservice_id=prod.get("freshservice_id"))
        _save("integration_events.json", events)
        return {"product": prod}

    prod["updated_at"] = _now()
    _save("catalog_and_kb.json", catalog)

    _record_event(events, account_id, "succeeded", "update_product", {"account_id": account_id, "product_id": product_id, "workspace_id": workspace_id, "name": name, "description": description, "status": status},
                  affected_collection="catalog_and_kb", affected_id=product_id, vendor_freshservice_id=prod.get("freshservice_id"))
    _save("integration_events.json", events)

    return {"product": prod}

