                                  affected_collection="people_and_groups", affected_id=r.get("id"), vendor_freshservice_id=r.get("freshservice_id"),
                                  error_message="Email already exists.")
                    _save("integration_events.json", events)
                    return _err("CONFLICT", "A requester with this email already exists.", email=email.strip())

    # Assign a placeholder freshservice_id integer surrogate (negative unique), since tool doesn't take vendor id
    used_ids = {r.get("freshservice_id") for r in pag if r.get("account_id") == account_id and r.get("entity_type") == "requester" and isinstance(r.get("freshservice_id"), int)}
    fs_id = -1
    while fs_id in used_ids:
        fs_id -= 1

    now = _now()
    row = {
        "id": _new_id("fsx"),
        "account_id": account_id,
        "entity_type": "requester",
        "freshservice_id": fs_id,
        "group_kind": None,
        "group_visibility": None,
        "parent_group_id": None,
        "member_person_id": None,
        "name": name.strip(),
        "email": email.strip() if isinstance(email, str) else None,
        "mobile": mobile,
        "title": title,
        "active": True if active is None else active,
        "custom_fields": custom_fields,
        "fields_schema_cache": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    pag.append(row)
    _save("people_and_groups.json", pag)

    _record_event(events, account_id, "succeeded", "create_requester", {"account_id": account_id, "name": name, "email": email, "mobile": mobile, "title": title, "active": active, "custom_fields": custom_fields},
                  affected_collection="people_and_groups", affected_id=row["id"], vendor_freshservice_id=row["freshservice_id"])
    _save("integration_events.json", events)

    return {"requester": row}

def get_all_requesters(account_id, limit=None, cursor=None, sort_by=None, sort_order=None, status=None, **_extra):
    import json, os, datetime, time, re, base64, secrets

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(8).upper()}"

    def _record_event(events, acc_id, status2, tool_name, params, affected_collection=None, affected_id=None, vendor_freshservice_id=None, error_message=None, http_method=None, endpoint=None):
        now = _now()
        ev = {
            "id": _new_id("evt"),
            "account_id": acc_id,
            "tool_name": tool_name,
            "request_params": params if isinstance(params, dict) else {},
            "http_method": http_method,
            "endpoint": endpoint,
            "status": "queued",
            "error_message": None,
            "affected_collection": affected_collection,
            "affected_id": affected_id,
            "vendor_freshservice_id": vendor_freshservice_id,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        ev["status"] = status2
        ev["error_message"] = error_message
        ev["duration_ms"] = max(0, int((time.time() - _t0) * 1000))
        ev["updated_at"] = _now()
        return ev

    def _encode_cursor(o):
        raw = json.dumps(o, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]+$", account_id):
        return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit", minimum=1, maximum=200)

    if sort_by is None:
        sort_by = "created_at"
    if sort_order is None:
        sort_order = "asc"

    if sort_by not in {"created_at", "updated_at", "name", "email", "freshservice_id"}:
        return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
    if sort_order not in {"asc", "desc"}:
        return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")
    if status is not None and status not in {"active", "inactive", "deleted"}:
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

    accounts = _load("fs_accounts.json")
    pag = _load("people_and_groups.json")
    events = _load("integration_events.json")

    acc = next((a for a in accounts if a.get("id") == account_id), None)
    if not acc:
        _record_event(events, account_id, "failed", "get_all_requesters",
                      {"account_id": account_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order, "status": status},
                      affected_collection="people_and_groups", error_message="Account not found.")
        _save("integration_events.json", events)
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    if acc.get("status") != "active":
        _record_event(events, account_id, "failed", "get_all_requesters",
                      {"account_id": account_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order, "status": status},
                      affected_collection="people_and_groups", error_message="Account is not active.")
        _save("integration_events.json", events)
        return _err("UNAUTHORIZED", "Account is not active.", account_id=account_id)

    # Filter
    rows = [r for r in pag if r.get("account_id") == account_id and r.get("entity_type") == "requester"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # Sort with stable tie-breaker
    def _key(r):
        v = r.get(sort_by)
        if v is None:
            # place None last in asc, first in desc by using sentinel
            v = "" if sort_by in ("name", "email") else -10**18
        if sort_by in ("created_at", "updated_at"):
            v = v if isinstance(v, str) else ""
        elif sort_by in ("name", "email"):
            v = v.strip().lower() if isinstance(v, str) else ""
        elif sort_by == "freshservice_id":
            v = v if isinstance(v, int) else -10**18
        return (v, r.get("id") or "")

    reverse = (sort_order == "desc")
    rows_sorted = sorted(rows, key=_key, reverse=reverse)

    # Pagination by opaque cursor carrying last seen sort value and id
    cur = _decode_cursor(cursor)
    if cursor is not None and cur is None:
        _record_event(events, account_id, "failed", "get_all_requesters",
                      {"account_id": account_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order, "status": status},
                      affected_collection="people_and_groups", error_message="Invalid cursor.")
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    start_idx = 0
    if cur is not None:
        if cur.get("v_sort_by") != sort_by or cur.get("v_sort_order") != sort_order or cur.get("v_status") != status:
            _record_event(events, account_id, "failed", "get_all_requesters",
                          {"account_id": account_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order, "status": status},
                          affected_collection="people_and_groups", error_message="Cursor does not match query.")
            _save("integration_events.json", events)
            return _err("VALIDATION_ERROR", "Cursor does not match the current query.", field="cursor")

        last_id = cur.get("last_id")
        # Find position strictly after last_id in sorted list
        if isinstance(last_id, str):
            for i, r in enumerate(rows_sorted):
                if r.get("id") == last_id:
                    start_idx = i + 1
                    break
            else:
                start_idx = 0

    page = rows_sorted[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows_sorted)
    next_cursor = None
    if has_more and page:
        next_cursor = _encode_cursor({
            "v_sort_by": sort_by,
            "v_sort_order": sort_order,
            "v_status": status,
            "last_id": page[-1].get("id"),
        })

    _record_event(events, account_id, "succeeded", "get_all_requesters",
                  {"account_id": account_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order, "status": status},
                  affected_collection="people_and_groups")
    _save("integration_events.json", events)

    return {
        "requesters": page,
        "meta": {
            "total": len(rows_sorted),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_requester_id(account_id, requester_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_event(account_row, status, error_message=None, affected_collection=None, affected_id=None, vendor_freshservice_id=None, endpoint=None, http_method=None):
        events = _load("integration_events.json")
        # id convention: iev_<hex>
        import secrets
        eid = "iev_" + secrets.token_hex(12).upper()
        dur = int(max(0, (time.time() - _t0) * 1000))
        ev = {
            "id": eid,
            "account_id": account_row["id"] if account_row else (account_id if isinstance(account_id, str) else None),
            "tool_name": "get_requester_id",
            "request_params": {"account_id": account_id, "requester_id": requester_id},
            "http_method": http_method,
            "endpoint": endpoint,
            "status": "queued",
            "error_message": None,
            "affected_collection": affected_collection,
            "affected_id": affected_id,
            "vendor_freshservice_id": vendor_freshservice_id,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        # transition queued -> final exactly once
        ev["status"] = status
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ev["duration_ms"] = dur
        if error_message:
            ev["error_message"] = error_message
        _save("integration_events.json", events)

    def _validate():
        if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]+$", account_id):
            return _err("VALIDATION_ERROR", "account_id is invalid; expected ^fsa_[0-9A-Z]+$.")
        if not isinstance(requester_id, str) or not re.match(r"^fsp_[0-9A-Z]+$", requester_id):
            return _err("VALIDATION_ERROR", "requester_id is invalid; expected ^fsp_[0-9A-Z]+$.")
        return None

    v = _validate()
    if v:
        # best-effort: still log against an active account if any; else log with provided account_id
        accounts = _load("fs_accounts.json")
        active = next((a for a in accounts if a.get("status") == "active"), None)
        if active:
            _append_event(active, "failed", error_message=v["error"]["message"], affected_collection="people_and_groups", affected_id=requester_id)
        else:
            # no active accounts exist, cannot associate properly
            _append_event({"id": account_id}, "failed", error_message=v["error"]["message"], affected_collection="people_and_groups", affected_id=requester_id)
        return v

    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        # Must write failed event; associate with some active account if possible, else with requested id
        fallback = next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(fallback if fallback else {"id": account_id}, "failed", error_message="No active account context available for this invocation.")
        return _err("UNAUTHORIZED", "No active Freshservice account available for this invocation.")

    rows = _load("people_and_groups.json")
    row = next((r for r in rows if r.get("id") == requester_id), None)
    if not row:
        _append_event(acct, "failed", error_message="Requester not found.", affected_collection="people_and_groups", affected_id=requester_id)
        return _err("NOT_FOUND", "No requester with that id exists in this account.")
    if row.get("account_id") != account_id:
        _append_event(acct, "failed", error_message="Requester does not belong to the specified account.", affected_collection="people_and_groups", affected_id=requester_id)
        return _err("UNAUTHORIZED", "Requester is not owned by the specified account.")
    if row.get("entity_type") != "requester":
        _append_event(acct, "failed", error_message="Record is not a requester.", affected_collection="people_and_groups", affected_id=requester_id, vendor_freshservice_id=row.get("freshservice_id"))
        return _err("NOT_FOUND", "No requester with that id exists in this account.")

    _append_event(acct, "succeeded", affected_collection="people_and_groups", affected_id=requester_id, vendor_freshservice_id=row.get("freshservice_id"))
    return {"requester": row}

def update_requester(account_id, requester_id, name=None, email=None, mobile=None, title=None, active=None, custom_fields=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_event(account_row, status_ev, error_message=None, affected_collection=None, affected_id=None, vendor_freshservice_id=None):
        events = _load("integration_events.json")
        import secrets
        eid = "iev_" + secrets.token_hex(12).upper()
        dur = int(max(0, (time.time() - _t0) * 1000))
        ev = {
            "id": eid,
            "account_id": account_row["id"] if account_row else (account_id if isinstance(account_id, str) else None),
            "tool_name": "update_requester",
            "request_params": {
                "account_id": account_id,
                "requester_id": requester_id,
                **({} if name is None else {"name": name}),
                **({} if email is None else {"email": email}),
                **({} if mobile is None else {"mobile": mobile}),
                **({} if title is None else {"title": title}),
                **({} if active is None else {"active": active}),
                **({} if custom_fields is None else {"custom_fields": custom_fields}),
                **({} if status is None else {"status": status}),
            },
            "http_method": None,
            "endpoint": None,
            "status": "queued",
            "error_message": None,
            "affected_collection": affected_collection,
            "affected_id": affected_id,
            "vendor_freshservice_id": vendor_freshservice_id,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        ev["status"] = status_ev
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ev["duration_ms"] = dur
        if error_message:
            ev["error_message"] = error_message
        _save("integration_events.json", events)

    # Validate ids
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]+$", account_id):
        accounts = _load("fs_accounts.json")
        active_acct = next((a for a in accounts if a.get("status") == "active"), None)
        msg = "account_id is invalid; expected ^fsa_[0-9A-Z]+$."
        _append_event(active_acct if active_acct else {"id": account_id}, "failed", error_message=msg, affected_collection="people_and_groups", affected_id=requester_id)
        return _err("VALIDATION_ERROR", msg)
    if not isinstance(requester_id, str) or not re.match(r"^fsp_[0-9A-Z]+$", requester_id):
        accounts = _load("fs_accounts.json")
        active_acct = next((a for a in accounts if a.get("status") == "active"), None)
        msg = "requester_id is invalid; expected ^fsp_[0-9A-Z]+$."
        _append_event(active_acct if active_acct else {"id": account_id}, "failed", error_message=msg, affected_collection="people_and_groups", affected_id=requester_id)
        return _err("VALIDATION_ERROR", msg)

    # Validate update payload not empty
    if all(v is None for v in [name, email, mobile, title, active, custom_fields, status]):
        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
        if acct:
            _append_event(acct, "failed", error_message="Empty update payload.", affected_collection="people_and_groups", affected_id=requester_id)
        else:
            fallback = next((a for a in accounts if a.get("status") == "active"), None)
            _append_event(fallback if fallback else {"id": account_id}, "failed", error_message="Empty update payload.", affected_collection="people_and_groups", affected_id=requester_id)
        return _err("VALIDATION_ERROR", "At least one field must be provided to update.")

    # Type validations
    if name is not None and not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string.")
    if email is not None and not isinstance(email, str):
        return _err("VALIDATION_ERROR", "email must be a string.")
    if mobile is not None and not isinstance(mobile, str):
        return _err("VALIDATION_ERROR", "mobile must be a string.")
    if title is not None and not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string.")
    if active is not None and not isinstance(active, bool):
        return _err("VALIDATION_ERROR", "active must be a boolean.")
    if custom_fields is not None and not isinstance(custom_fields, dict):
        return _err("VALIDATION_ERROR", "custom_fields must be an object.")
    if status is not None and status not in ("active", "inactive", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive, deleted.")

    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        fallback = next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(fallback if fallback else {"id": account_id}, "failed", error_message="No active account context available for this invocation.")
        return _err("UNAUTHORIZED", "No active Freshservice account available for this invocation.")

    rows = _load("people_and_groups.json")
    idx = next((i for i, r in enumerate(rows) if r.get("id") == requester_id), None)
    if idx is None:
        _append_event(acct, "failed", error_message="Requester not found.", affected_collection="people_and_groups", affected_id=requester_id)
        return _err("NOT_FOUND", "Requester not found.")
    row = rows[idx]

    if row.get("account_id") != account_id:
        _append_event(acct, "failed", error_message="Requester not owned by account.", affected_collection="people_and_groups", affected_id=requester_id)
        return _err("UNAUTHORIZED", "Requester is not owned by the specified account.")
    if row.get("entity_type") != "requester":
        _append_event(acct, "failed", error_message="Record is not a requester.", affected_collection="people_and_groups", affected_id=requester_id)
        return _err("NOT_FOUND", "Requester not found.")

    if row.get("status") == "deleted":
        # cannot modify deleted row
        _append_event(acct, "failed", error_message="Cannot modify a deleted requester.", affected_collection="people_and_groups", affected_id=requester_id, vendor_freshservice_id=row.get("freshservice_id"))
        return _err("CONFLICT", "Cannot modify a deleted requester.")

    # Enforce lifecycle transitions if status provided
    if status is not None:
        cur = row.get("status")
        allowed = {
            "active": {"inactive", "deleted"},
            "inactive": {"active", "deleted"},
            "deleted": set(),
        }
        if cur not in allowed:
            _append_event(acct, "failed", error_message="Invalid current status.", affected_collection="people_and_groups", affected_id=requester_id, vendor_freshservice_id=row.get("freshservice_id"))
            return _err("CONFLICT", "Invalid current status on record.")
        if status != cur and status not in allowed[cur]:
            _append_event(acct, "failed", error_message="Invalid status transition.", affected_collection="people_and_groups", affected_id=requester_id, vendor_freshservice_id=row.get("freshservice_id"))
            return _err("INVALID_TRANSITION", f"Illegal status transition from {cur} to {status}.")
        row["status"] = status

    # Uniqueness constraint: unique(account_id, entity_type, email) where entity_type in ('requester','agent') and email is not null and status <> 'deleted'
    if email is not None:
        new_email = email.strip()
        if new_email == "":
            new_email = email  # keep as provided; allow vendor to send empty? treat as value
        conflict = next(
            (r for r in rows
             if r.get("id") != requester_id
             and r.get("account_id") == account_id
             and r.get("entity_type") in ("requester", "agent")
             and r.get("status") != "deleted"
             and r.get("email") is not None
             and r.get("email") == new_email),
            None
        )
        if conflict:
            _append_event(acct, "failed", error_message="Email already in use.", affected_collection="people_and_groups", affected_id=requester_id, vendor_freshservice_id=row.get("freshservice_id"))
            return _err("CONFLICT", "email is already used by another person in this account.")
        row["email"] = new_email

    # Apply remaining updates
    if name is not None:
        row["name"] = name
    if mobile is not None:
        row["mobile"] = mobile
    if title is not None:
        row["title"] = title
    if active is not None:
        row["active"] = active
    if custom_fields is not None:
        row["custom_fields"] = custom_fields

    row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    rows[idx] = row
    _save("people_and_groups.json", rows)

    _append_event(acct, "succeeded", affected_collection="people_and_groups", affected_id=requester_id, vendor_freshservice_id=row.get("freshservice_id"))
    return {"requester": row}

def filter_requesters(account_id, query=None, email=None, active=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_event(account_row, status_ev, error_message=None, affected_collection=None):
        events = _load("integration_events.json")
        import secrets
        eid = "iev_" + secrets.token_hex(12).upper()
        dur = int(max(0, (time.time() - _t0) * 1000))
        ev = {
            "id": eid,
            "account_id": account_row["id"] if account_row else (account_id if isinstance(account_id, str) else None),
            "tool_name": "filter_requesters",
            "request_params": {
                "account_id": account_id,
                **({} if query is None else {"query": query}),
                **({} if email is None else {"email": email}),
                **({} if active is None else {"active": active}),
                **({} if status is None else {"status": status}),
                **({} if limit is None else {"limit": limit}),
                **({} if cursor is None else {"cursor": cursor}),
                **({} if sort_by is None else {"sort_by": sort_by}),
                **({} if sort_order is None else {"sort_order": sort_order}),
            },
            "http_method": None,
            "endpoint": None,
            "status": "queued",
            "error_message": None,
            "affected_collection": affected_collection,
            "affected_id": None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        ev["status"] = status_ev
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ev["duration_ms"] = dur
        if error_message:
            ev["error_message"] = error_message
        _save("integration_events.json", events)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]+$", account_id):
        accounts = _load("fs_accounts.json")
        active_acct = next((a for a in accounts if a.get("status") == "active"), None)
        msg = "account_id is invalid; expected ^fsa_[0-9A-Z]+$."
        _append_event(active_acct if active_acct else {"id": account_id}, "failed", error_message=msg, affected_collection="people_and_groups")
        return _err("VALIDATION_ERROR", msg)

    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string.")
    if email is not None and not isinstance(email, str):
        return _err("VALIDATION_ERROR", "email must be a string.")
    if active is not None and not isinstance(active, bool):
        return _err("VALIDATION_ERROR", "active must be a boolean.")
    if status is not None and status not in ("active", "inactive", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive, deleted.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at", "name", "email", "freshservice_id"):
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, name, email, freshservice_id.")
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc.")

    # Auth/account
    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        fallback = next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(fallback if fallback else {"id": account_id}, "failed", error_message="No active account context available for this invocation.", affected_collection="people_and_groups")
        return _err("UNAUTHORIZED", "You do not have access to that tenant (no active account).")

    # Decode cursor (opaque): base64url of integer offset
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if not re.match(r"^[0-9]+$", raw):
                _append_event(acct, "failed", error_message="Invalid cursor.", affected_collection="people_and_groups")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            offset = int(raw)
            if offset < 0:
                _append_event(acct, "failed", error_message="Invalid cursor.", affected_collection="people_and_groups")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except Exception:
            _append_event(acct, "failed", error_message="Invalid cursor.", affected_collection="people_and_groups")
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    rows = _load("people_and_groups.json")
    reqs = [r for r in rows if r.get("account_id") == account_id and r.get("entity_type") == "requester"]

    # Filters
    if email is not None:
        reqs = [r for r in reqs if r.get("email") == email]
    if active is not None:
        reqs = [r for r in reqs if r.get("active") is active]
    if status is not None:
        reqs = [r for r in reqs if r.get("status") == status]
    if query is not None and query.strip() != "":
        q = query.strip().lower()
        def _match(r):
            n = (r.get("name") or "").lower()
            e = (r.get("email") or "").lower()
            return (q in n) or (q in e)
        reqs = [r for r in reqs if _match(r)]

    # Sort
    def _key(r):
        v = r.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            # ISO strings sort lexicographically if normalized; None last
            return (v is None, v or "")
        if sort_by in ("name", "email"):
            return (v is None, (v or "").lower())
        if sort_by == "freshservice_id":
            return (v is None, v if isinstance(v, int) else -1)
        return (v is None, v)
    reverse = (sort_order == "desc")
    reqs_sorted = sorted(reqs, key=_key, reverse=reverse)

    total = len(reqs_sorted)
    page = reqs_sorted[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("utf-8").rstrip("=")

    _append_event(acct, "succeeded", affected_collection="people_and_groups")
    return {
        "requesters": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order,
        }
    }

def create_agent(account_id, agent, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1])
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _event_id():
        return "evt_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=")

    def _new_person_id():
        return "fsp_" + base64.b32encode(os.urandom(8)).decode("ascii").rstrip("=")

    def _email_ok(e):
        if not isinstance(e, str):
            return False
        e = e.strip()
        if len(e) < 3 or "@" not in e:
            return False
        local, _, dom = e.partition("@")
        if not local or not dom or "." not in dom:
            return False
        if any(c.isspace() for c in e):
            return False
        return True

    start = time.time()
    events = _load("integration_events.json")

    # Choose an active account that satisfies prerequisites (must be active).
    accounts = _load("fs_accounts.json")
    acct = None
    if isinstance(account_id, str):
        for a in accounts:
            if a.get("id") == account_id and a.get("status") == "active":
                acct = a
                break

    ev = {
        "id": _event_id(),
        "account_id": account_id if isinstance(account_id, str) else None,
        "tool_name": "create_agent",
        "request_params": {"account_id": account_id, "agent": agent} if isinstance(account_id, str) else {"account_id": account_id, "agent": agent},
        "http_method": "POST",
        "endpoint": "/agents",
        "status": "queued",
        "error_message": None,
        "affected_collection": "people_and_groups",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    events.append(ev)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None, affected_id=None):
        end = time.time()
        duration_ms = int(max(0, round((end - start) * 1000)))
        events2 = _load("integration_events.json")
        for row in events2:
            if row.get("id") == ev["id"]:
                if row.get("status") != "queued":
                    # Should not happen; keep original but do not crash.
                    break
                row["status"] = status
                row["error_message"] = error_message
                row["duration_ms"] = duration_ms
                row["updated_at"] = _now()
                if affected_id is not None:
                    row["affected_id"] = affected_id
                break
        _save("integration_events.json", events2)

    # UNAUTHORIZED if no active account row matches
    if acct is None:
        _finalize("failed", "No active account available for requested account_id.")
        return _err("UNAUTHORIZED", "Unauthorized: no active Freshservice account for this request.", account_id=account_id)

    # Validate account_id format
    if not re.match(r"^fsa_[0-9A-Z]{4,}$", account_id or ""):
        _finalize("failed", "Invalid account_id format.")
        return _err("VALIDATION_ERROR", "Invalid account_id format.", field="account_id")

    # Validate agent object and allowed fields
    if not isinstance(agent, dict):
        _finalize("failed", "Agent must be an object.")
        return _err("VALIDATION_ERROR", "agent must be an object.", field="agent")

    allowed = {"name", "email", "mobile", "title", "active", "custom_fields"}
    extra_keys = [k for k in agent.keys() if k not in allowed]
    if extra_keys:
        _finalize("failed", "Extra fields provided in agent.")
        return _err("VALIDATION_ERROR", "agent has unknown fields.", field="agent", extra_fields=extra_keys)

    # Required
    if "name" not in agent or "email" not in agent:
        _finalize("failed", "Missing required fields name/email.")
        return _err("VALIDATION_ERROR", "agent.name and agent.email are required.", field="agent")

    name = agent.get("name")
    email = agent.get("email")

    if not isinstance(name, str) or not name.strip():
        _finalize("failed", "Invalid name.")
        return _err("VALIDATION_ERROR", "agent.name must be a non-empty string.", field="agent.name")

    if not _email_ok(email):
        _finalize("failed", "Invalid email.")
        return _err("VALIDATION_ERROR", "agent.email must be a valid email address.", field="agent.email")

    # Type validation for optional fields
    if "mobile" in agent and agent.get("mobile") is not None and not isinstance(agent.get("mobile"), str):
        _finalize("failed", "Invalid mobile type.")
        return _err("VALIDATION_ERROR", "agent.mobile must be a string.", field="agent.mobile")
    if "title" in agent and agent.get("title") is not None and not isinstance(agent.get("title"), str):
        _finalize("failed", "Invalid title type.")
        return _err("VALIDATION_ERROR", "agent.title must be a string.", field="agent.title")
    if "active" in agent and agent.get("active") is not None and not isinstance(agent.get("active"), bool):
        _finalize("failed", "Invalid active type.")
        return _err("VALIDATION_ERROR", "agent.active must be a boolean.", field="agent.active")
    if "custom_fields" in agent and agent.get("custom_fields") is not None and not isinstance(agent.get("custom_fields"), dict):
        _finalize("failed", "Invalid custom_fields type.")
        return _err("VALIDATION_ERROR", "agent.custom_fields must be an object.", field="agent.custom_fields")

    # Ensure uniqueness: unique(account_id, entity_type, email) where entity_type='agent' and status <> 'deleted'
    pag = _load("people_and_groups.json")
    norm_email = email.strip().lower()
    for row in pag:
        if row.get("account_id") == account_id and row.get("entity_type") == "agent":
            row_email = row.get("email")
            if isinstance(row_email, str) and row_email.strip().lower() == norm_email and row.get("status") != "deleted":
                _finalize("failed", "Agent with same email already exists.")
                return _err("CONFLICT", "Agent with this email already exists.", field="agent.email", email=email)

    # Create record
    new_id = _new_person_id()
    now = _now()

    # choose a freshservice_id if possible: avoid duplicates if we generate
    existing_fsids = set()
    for row in pag:
        if row.get("account_id") == account_id and row.get("entity_type") == "agent" and isinstance(row.get("freshservice_id"), int):
            existing_fsids.add(row["freshservice_id"])
    freshservice_id = None
    if existing_fsids:
        freshservice_id = max(existing_fsids) + 1
    else:
        # derive a stable-ish integer from local id
        freshservice_id = int.from_bytes(hashlib.sha1(new_id.encode("utf-8")).digest()[:4], "big") % 2000000000 + 1
        # ensure no collision
        while freshservice_id in existing_fsids:
            freshservice_id += 1

    rec = {
        "id": new_id,
        "account_id": account_id,
        "entity_type": "agent",
        "freshservice_id": freshservice_id,
        "group_kind": None,
        "group_visibility": None,
        "parent_group_id": None,
        "member_person_id": None,
        "name": name.strip(),
        "email": email.strip(),
        "mobile": agent.get("mobile"),
        "title": agent.get("title"),
        "active": agent.get("active", True) if agent.get("active") is not None else True,
        "custom_fields": agent.get("custom_fields"),
        "fields_schema_cache": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    pag.append(rec)
    _save("people_and_groups.json", pag)
    _finalize("succeeded", None, affected_id=new_id)

    return {"agent": rec}

def get_agent(account_id, agent_id, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_urlsafe(18).replace('-','').replace('_','')}"[:32]

    def _finalize_event(ev_id, statusv, error_message=None, affected_id=None, vendor_id=None, t0=None):
        events2 = _load("integration_events.json")
        for r in events2:
            if r.get("id") == ev_id and r.get("status") == "queued":
                r["status"] = statusv
                r["error_message"] = error_message
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000)) if isinstance(t0, (int, float)) else 0
                r["updated_at"] = _utcnow_z()
                if affected_id is not None:
                    r["affected_id"] = affected_id
                if vendor_id is not None:
                    r["vendor_freshservice_id"] = vendor_id
                break
        _save("integration_events.json", events2)

    t0 = time.time()
    now = _utcnow_z()
    params = {"account_id": account_id, "agent_id": agent_id}

    ev_id = _new_id("fse")
    events = _load("integration_events.json")
    events.append(
        {
            "id": ev_id,
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "get_agent",
            "request_params": params,
            "http_method": "GET",
            "endpoint": f"/agents/{agent_id}",
            "status": "queued",
            "error_message": None,
            "affected_collection": "people_and_groups",
            "affected_id": agent_id if isinstance(agent_id, str) else None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
    )
    _save("integration_events.json", events)

    try:
        if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]{4,}$", account_id):
            _finalize_event(ev_id, "failed", "Invalid account_id.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
        if not isinstance(agent_id, str) or not re.match(r"^fsp_[0-9A-Z]{4,}$", agent_id):
            _finalize_event(ev_id, "failed", "Invalid agent_id.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid agent_id.", field="agent_id")

        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if not acct:
            _finalize_event(ev_id, "failed", "Account not found.", t0=t0)
            return _err("NOT_FOUND", "Account not found.", account_id=account_id)
        if acct.get("status") != "active":
            _finalize_event(ev_id, "failed", "Account is not active.", t0=t0)
            return _err("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status"))

        pag = _load("people_and_groups.json")
        agent = next((p for p in pag if p.get("id") == agent_id), None)
        if not agent:
            _finalize_event(ev_id, "failed", "Agent not found.", t0=t0)
            return _err("NOT_FOUND", "Agent not found.", agent_id=agent_id)
        # Not UNAUTHORIZED; mismatch is effectively "not in tenant"
        if agent.get("account_id") != account_id:
            _finalize_event(ev_id, "failed", "Agent not found in account.", t0=t0)
            return _err("NOT_FOUND", "Agent not found in account.", agent_id=agent_id, account_id=account_id)
        if agent.get("entity_type") != "agent":
            _finalize_event(ev_id, "failed", "agent_id does not refer to an agent.", t0=t0)
            return _err("NOT_FOUND", "No such agent exists.", agent_id=agent_id)
        if agent.get("status") == "deleted":
            _finalize_event(ev_id, "failed", "Agent is deleted.", t0=t0)
            return _err("NOT_FOUND", "No such agent exists.", agent_id=agent_id)

        _finalize_event(ev_id, "succeeded", affected_id=agent_id, vendor_id=agent.get("freshservice_id"), t0=t0)
        return {"agent": agent}
    except Exception as e:
        _finalize_event(ev_id, "failed", f"Unexpected error: {type(e).__name__}", t0=t0)
        return _err("CONFLICT", "Unexpected error occurred.", detail=f"{type(e).__name__}")

