    if sort_order is None:
        sort_order = "asc"
    if sort_order not in {"asc", "desc"}:
        _finalize("failed", "Invalid sort_order.")
        return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order", allowed=["asc", "desc"])

    start_idx = 0
    if cursor is not None:
        start_idx = _decode_cursor(cursor)
        if start_idx is None:
            _finalize("failed", "Malformed cursor.")
            return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    pag = _load("people_and_groups.json")
