def filter_agents(account_id, query, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1])
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _event_id():
        return "evt_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=")

    def _encode_cursor(idx):
        payload = f"i:{idx}"
        return base64.urlsafe_b64encode(payload.encode("utf-8")).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if not isinstance(c, str) or not c:
            return 0
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
        except Exception:
            return None
        if not raw.startswith("i:"):
            return None
        try:
            i = int(raw[2:])
            if i < 0:
                return None
            return i
        except Exception:
            return None

    start = time.time()
    events = _load("integration_events.json")
    accounts = _load("fs_accounts.json")

    acct = None
    if isinstance(account_id, str):
        for a in accounts:
            if a.get("id") == account_id and a.get("status") == "active":
                acct = a
                break

    ev = {
        "id": _event_id(),
        "account_id": account_id if isinstance(account_id, str) else None,
        "tool_name": "filter_agents",
        "request_params": {
            "account_id": account_id,
            "query": query,
            "limit": limit,
            "cursor": cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
        "http_method": "GET",
        "endpoint": "/agents/search",
        "status": "queued",
        "error_message": None,
        "affected_collection": "people_and_groups",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    events.append(ev)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None):
        end = time.time()
        duration_ms = int(max(0, round((end - start) * 1000)))
        events2 = _load("integration_events.json")
        for row in events2:
            if row.get("id") == ev["id"]:
                if row.get("status") != "queued":
                    break
                row["status"] = status
                row["error_message"] = error_message
                row["duration_ms"] = duration_ms
                row["updated_at"] = _now()
                break
        _save("integration_events.json", events2)

    if acct is None:
        _finalize("failed", "No active account available for requested account_id.")
        return _err("UNAUTHORIZED", "Unauthorized: no active Freshservice account for this request.", account_id=account_id)

    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]{4,}$", account_id):
        _finalize("failed", "Invalid account_id format.")
        return _err("VALIDATION_ERROR", "Invalid account_id format.", field="account_id")

    if not isinstance(query, str) or not query.strip():
        _finalize("failed", "Empty/invalid query.")
        return _err("VALIDATION_ERROR", "query must be a non-empty string.", field="query")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _finalize("failed", "Invalid limit.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    allowed_sort_by = {"created_at", "updated_at", "name", "email", "freshservice_id"}
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in allowed_sort_by:
        _finalize("failed", "Invalid sort_by.")
        return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by", allowed=sorted(list(allowed_sort_by)))

    if sort_order is None:
        sort_order = "asc"
    if sort_order not in {"asc", "desc"}:
        _finalize("failed", "Invalid sort_order.")
        return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order", allowed=["asc", "desc"])

    start_idx = 0
    if cursor is not None:
        start_idx = _decode_cursor(cursor)
        if start_idx is None:
            _finalize("failed", "Malformed cursor.")
            return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    q = query.strip()
    ql = q.lower()

    # Minimal Freshservice-like search: support token matches and simple field qualifiers:
    # email:<substr>, name:<substr>, active:true/false, status:<value>
    tokens = [t for t in re.split(r"\s+", q) if t]
    qualifiers = {}
    free_terms = []
    for t in tokens:
        if ":" in t:
            k, v = t.split(":", 1)
            k = k.strip().lower()
            v = v.strip()
            if k and v:
                qualifiers.setdefault(k, []).append(v)
            else:
                free_terms.append(t)
        else:
            free_terms.append(t)

    def _matches(agent_row):
        if agent_row.get("account_id") != account_id or agent_row.get("entity_type") != "agent":
            return False

        # qualifiers
        for k, vals in qualifiers.items():
            if k == "email":
                email = (agent_row.get("email") or "").lower()
                if not any(v.lower() in email for v in vals):
                    return False
            elif k == "name":
                name = (agent_row.get("name") or "").lower()
                if not any(v.lower() in name for v in vals):
                    return False
            elif k == "status":
                st = (agent_row.get("status") or "").lower()
                if not any(v.lower() == st for v in vals):
                    return False
            elif k == "active":
                av = agent_row.get("active")
                want_any = False
                ok = False
                for v in vals:
                    vl = v.lower()
                    if vl in ("true", "false"):
                        want_any = True
                        if isinstance(av, bool) and ((vl == "true" and av) or (vl == "false" and not av)):
                            ok = True
                    else:
                        # unknown value -> invalid query
                        return None
                if want_any and not ok:
                    return False
            else:
                # unknown qualifier -> treat as invalid query
                return None

        # free terms: match in name/email/mobile/title
        hay = " ".join([
            (agent_row.get("name") or ""),
            (agent_row.get("email") or ""),
            (agent_row.get("mobile") or ""),
            (agent_row.get("title") or ""),
        ]).lower()
        for term in free_terms:
            tl = term.lower()
            if tl not in hay:
                return False
        return True

    pag = _load("people_and_groups.json")
    matches = []
    for r in pag:
        m = _matches(r)
        if m is None:
            _finalize("failed", "Invalid query: unknown qualifier or value.")
            return _err("VALIDATION_ERROR", "Invalid query.", field="query")
        if m:
            matches.append(r)

    def _key(r):
        v = r.get(sort_by)
        if sort_by in {"created_at", "updated_at"}:
            dt = _parse_dt(v)
            return dt or datetime.datetime.min
        if sort_by in {"name", "email"}:
            return (v or "").strip().lower()
        if sort_by == "freshservice_id":
            return v if isinstance(v, int) else -1
        return v

    reverse = sort_order == "desc"
    matches_sorted = sorted(matches, key=_key, reverse=reverse)

    total = len(matches_sorted)
    page = matches_sorted[start_idx:start_idx + limit]
    next_cursor = None
    if start_idx + limit < total:
        next_cursor = _encode_cursor(start_idx + limit)

    _finalize("succeeded", None)
    return {
        "agents": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None,
        },
        "sort": {"sort_by": sort_by, "sort_order": sort_order},
        "query": query,
    }

def get_agent_fields(account_id, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_urlsafe(18).replace('-','').replace('_','')}"[:32]

    t0 = time.time()
    now = _utcnow_z()

    params = {"account_id": account_id}

    accounts = _load("fs_accounts.json")
    acct = None
    if isinstance(account_id, str):
        for a in accounts:
            if a.get("id") == account_id:
                acct = a
                break

    events = _load("integration_events.json")
    ev = {
        "id": _new_id("fse"),
        "account_id": account_id if isinstance(account_id, str) else None,
        "tool_name": "get_agent_fields",
        "request_params": params,
        "http_method": "GET",
        "endpoint": "/agents/fields",
        "status": "queued",
        "error_message": None,
        "affected_collection": "people_and_groups",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    events.append(ev)
    _save("integration_events.json", events)

    def _finalize(status, error_message=None):
        events2 = _load("integration_events.json")
        for r in events2:
            if r.get("id") == ev["id"] and r.get("status") == "queued":
                r["status"] = status
                r["error_message"] = error_message
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                r["updated_at"] = _utcnow_z()
                break
        _save("integration_events.json", events2)

    def _fail(code, msg, **x):
        _finalize("failed", msg)
        return _err(code, msg, **x)

    if not isinstance(account_id, str) or (not re.match(r"^fsa_[0-9A-Z]{4,}$", account_id) and not re.match(r"^fsa_[A-Za-z0-9]+$", account_id)):
        return _fail("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
    if acct is None:
        return _fail("NOT_FOUND", "Account not found.", account_id=account_id)
    if acct.get("status") != "active":
        return _fail("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status"))

    people = _load("people_and_groups.json")
    # Prefer any cached schema payload if present
    schemas = []
    for r in people:
        if r.get("account_id") == account_id and r.get("entity_type") == "agent":
            cache = r.get("fields_schema_cache")
            if isinstance(cache, dict) and cache:
                schemas.append(cache)
    if schemas:
        # If multiple, return the most recently updated agent cache
        def _key(x):
            return x.get("updated_at") or ""
        # But caches are dicts, not rows; just return unique caches
        _finalize("succeeded", None)
        return {"fields": schemas[0] if len(schemas) == 1 else schemas}

    # Fall back: derive a minimal "field definitions" list from actual agent rows
    agent_rows = [r for r in people if r.get("account_id") == account_id and r.get("entity_type") == "agent" and r.get("status") != "deleted"]
    custom_keys = set()
    for a in agent_rows:
        cf = a.get("custom_fields")
        if isinstance(cf, dict):
            for k in cf.keys():
                custom_keys.add(k)
    base_fields = [
        {"name": "name", "type": "string"},
        {"name": "email", "type": "string"},
        {"name": "mobile", "type": "string"},
        {"name": "title", "type": "string"},
        {"name": "active", "type": "boolean"},
    ]
    for k in sorted(custom_keys):
        base_fields.append({"name": f"custom_fields.{k}", "type": "string"})
    _finalize("succeeded", None)
    return {"fields": base_fields}

def get_all_agent_groups(account_id, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_event_id(events):
        mx = 0
        for e in events:
            s = str(e.get("id", ""))
            m = re.match(r"^ise_(\d+)$", s)
            if m:
                mx = max(mx, int(m.group(1)))
        return f"ise_{mx+1}"

    # --- validation ---
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]{4,}$", account_id):
        accounts = _load("fs_accounts.json")
        events = _load("integration_events.json")
        acct = next((a for a in accounts if a.get("status") == "active"), None)
        if acct:
            events.append({
                "id": _new_event_id(events),
                "account_id": acct.get("id"),
                "tool_name": "get_all_agent_groups",
                "request_params": {"account_id": account_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                "http_method": "GET",
                "endpoint": "/groups/agent",
                "status": "failed",
                "error_message": "VALIDATION_ERROR: invalid account_id",
                "affected_collection": "people_and_groups",
                "affected_id": None,
                "vendor_freshservice_id": None,
                "duration_ms": int((time.time() - t0) * 1000),
                "created_at": now,
                "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            })
            _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "account_id is invalid")

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_v = limit

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    allowed_sort_by = {"created_at", "updated_at", "name", "freshservice_id"}
    if sort_by is None:
        sort_by_v = "created_at"
    else:
        if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
            return _err("VALIDATION_ERROR", "sort_by is invalid")
        sort_by_v = sort_by

    if sort_order is None:
        sort_order_v = "asc"
    else:
        if not isinstance(sort_order, str) or sort_order not in {"asc", "desc"}:
            return _err("VALIDATION_ERROR", "sort_order is invalid")
        sort_order_v = sort_order

    # decode cursor as integer offset (base64 of "o:<int>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("o:"):
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    accounts = _load("fs_accounts.json")
    events = _load("integration_events.json")

    # queued event
    ev = {
        "id": _new_event_id(events),
        "account_id": account_id,
        "tool_name": "get_all_agent_groups",
        "request_params": {"account_id": account_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
        "http_method": "GET",
        "endpoint": "/groups/agent",
        "status": "queued",
        "error_message": None,
        "affected_collection": "people_and_groups",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    events.append(ev)
    _save("integration_events.json", events)

    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        ev["status"] = "failed"
        ev["error_message"] = "UNAUTHORIZED: no active account for account_id"
        ev["duration_ms"] = int((time.time() - t0) * 1000)
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("integration_events.json", events)
        return _err("UNAUTHORIZED", "No active account for the given account_id")

    # --- RATE LIMIT (tenant-level) ---
    # Simple rolling window: max 60 calls/min per account for this tool.
    window_s = 60
    max_calls = 60
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    recent = 0
    for e in events:
        if e.get("account_id") != account_id:
            continue
        if e.get("tool_name") != "get_all_agent_groups":
            continue
        dt = _parse_dt(e.get("created_at"))
        if dt and dt >= cutoff:
            recent += 1
    if recent > max_calls:
        ev["status"] = "failed"
        ev["error_message"] = "RATE_LIMIT: too many requests"
        ev["duration_ms"] = int((time.time() - t0) * 1000)
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("integration_events.json", events)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    pag = _load("people_and_groups.json")
    rows = [
        r for r in pag
        if r.get("account_id") == account_id
        and r.get("entity_type") == "group"
        and r.get("group_kind") == "agent_group"
        and r.get("status") != "deleted"
    ]

    def _sort_key(r):
        v = r.get(sort_by_v)
        if sort_by_v in ("created_at", "updated_at"):
            # ISO string sorts lexicographically OK if consistent; fallback empty
            return v if isinstance(v, str) else ""
        if sort_by_v == "name":
            return (v or "").lower() if isinstance(v, str) else ""
        if sort_by_v == "freshservice_id":
            return v if isinstance(v, int) else -1
        return ""

    reverse = (sort_order_v == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit_v]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8")

    ev["status"] = "succeeded"
    ev["duration_ms"] = int((time.time() - t0) * 1000)
    ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("integration_events.json", events)

    return {
        "agent_groups": page,
        "page_info": {
            "total": total,
            "limit": limit_v,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "sort": {"by": sort_by_v, "order": sort_order_v},
    }

