        _log_event(events, account_id, "update_group", params, "failed",
                   err="Invalid group_id", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "group_id is invalid", field="group_id")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log_event(events, account_id, "update_group", params, "failed",
                   err="Invalid name", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    if group_kind is not None and group_kind not in ("agent_group", "requester_group"):
        _log_event(events, account_id, "update_group", params, "failed",
                   err="Invalid group_kind", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "group_kind is invalid", field="group_kind")

    if group_visibility is not None and group_visibility not in ("manual", "dynamic"):
        _log_event(events, account_id, "update_group", params, "failed",
                   err="Invalid group_visibility", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "group_visibility is invalid", field="group_visibility")

    if parent_group_id is not None:
        if parent_group_id != "" and (not isinstance(parent_group_id, str) or not re.fullmatch(r"^fsp_[0-9A-Za-z]+$", parent_group_id)):
            _log_event(events, account_id, "update_group", params, "failed",
                       err="Invalid parent_group_id", affected_collection="people_and_groups", affected_id=group_id,
                       duration_ms=(time.time()-t0)*1000)
            _save("integration_events.json", events)
            return _err("VALIDATION_ERROR", "parent_group_id is invalid", field="parent_group_id")

    if active is not None and not isinstance(active, bool):
        _log_event(events, account_id, "update_group", params, "failed",
                   err="Invalid active", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "active must be boolean", field="active")

    if custom_fields is not None and not isinstance(custom_fields, dict):
        _log_event(events, account_id, "update_group", params, "failed",
                   err="Invalid custom_fields", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "custom_fields must be object", field="custom_fields")

    if status is not None and status not in ("active", "inactive", "deleted"):
        _log_event(events, account_id, "update_group", params, "failed",
                   err="Invalid status", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        _log_event(events, account_id, "update_group", params, "failed",
                   err="No active account context", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("UNAUTHORIZED", "No active account available for this operation")

    pag = _load("people_and_groups.json")
    grp = next((r for r in pag if r.get("id") == group_id and r.get("account_id") == account_id), None)
    if not grp:
        _log_event(events, account_id, "update_group", params, "failed",
                   err="Group not found", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("NOT_FOUND", "Group not found in tenant", group_id=group_id)

    if grp.get("entity_type") != "group":
        _log_event(events, account_id, "update_group", params, "failed",
                   err="ID is not a group", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("NOT_FOUND", "group_id does not refer to a group", group_id=group_id)

    # Forbid changing kind/visibility (not supported for existing record)
    if group_kind is not None and group_kind != grp.get("group_kind"):
        _log_event(events, account_id, "update_group", params, "failed",
                   err="group_kind change forbidden", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "Changing group_kind is not supported for existing groups", field="group_kind")

    if group_visibility is not None and group_visibility != grp.get("group_visibility"):
        _log_event(events, account_id, "update_group", params, "failed",
                   err="group_visibility change forbidden", affected_collection="people_and_groups", affected_id=group_id,
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "Changing group_visibility is not supported for existing groups", field="group_visibility")

    # Parent group checks (allow clearing by empty string)
    if parent_group_id is not None:
        if parent_group_id == "":
            parent_group_id_val = None
        else:
            parent_group_id_val = parent_group_id
            parent = next((r for r in pag if r.get("id") == parent_group_id_val and r.get("account_id") == account_id), None)
            if not parent:
                _log_event(events, account_id, "update_group", params, "failed",
                           err="Parent group not found", affected_collection="people_and_groups",
                           affected_id=parent_group_id_val, duration_ms=(time.time()-t0)*1000)
                _save("integration_events.json", events)
                return _err("NOT_FOUND", "parent_group_id not found in tenant", parent_group_id=parent_group_id_val)
            if parent.get("entity_type") != "group":
                _log_event(events, account_id, "update_group", params, "failed",
                           err="parent_group_id is not a group", affected_collection="people_and_groups",
                           affected_id=parent_group_id_val, duration_ms=(time.time()-t0)*1000)
                _save("integration_events.json", events)
                return _err("VALIDATION_ERROR", "parent_group_id must refer to a group", field="parent_group_id")
            if parent_group_id_val == group_id:
                _log_event(events, account_id, "update_group", params, "failed",
                           err="parent_group_id cannot equal group_id", affected_collection="people_and_groups",
                           affected_id=group_id, duration_ms=(time.time()-t0)*1000)
                _save("integration_events.json", events)
                return _err("VALIDATION_ERROR", "parent_group_id cannot equal group_id", field="parent_group_id")
    else:
        parent_group_id_val = None  # unused

    # Status transition enforcement
    lifecycle = {
        "active": {"inactive", "deleted"},
        "inactive": {"active", "deleted"},
        "deleted": set(),
    }
    if status is not None:
        cur = grp.get("status")
        if cur not in lifecycle:
            _log_event(events, account_id, "update_group", params, "failed",
                       err="Unknown current status", affected_collection="people_and_groups",
                       affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            _save("integration_events.json", events)
            return _err("VALIDATION_ERROR", "Current group status is invalid", current_status=cur)
        if status != cur and status not in lifecycle[cur]:
            _log_event(events, account_id, "update_group", params, "failed",
                       err="Illegal status transition", affected_collection="people_and_groups",
                       affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            _save("integration_events.json", events)
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=status)

    # Apply updates
    if name is not None:
        new_name = name.strip()
        # conflict check: same name & kind exists non-deleted
        existing = next((r for r in pag if r.get("account_id") == account_id and r.get("entity_type") == "group"
                         and r.get("id") != group_id
                         and (r.get("name") or "").strip().lower() == new_name.lower()
                         and r.get("group_kind") == grp.get("group_kind")
                         and r.get("status") != "deleted"), None)
        if existing:
            _log_event(events, account_id, "update_group", params, "failed",
                       err="Duplicate group name/kind", affected_collection="people_and_groups",
                       affected_id=existing.get("id"), duration_ms=(time.time()-t0)*1000)
            _save("integration_events.json", events)
            return _err("CONFLICT", "A group with the same name and kind already exists", existing_group_id=existing.get("id"))
        grp["name"] = new_name

    if parent_group_id is not None:
        grp["parent_group_id"] = parent_group_id_val

    if active is not None:
        grp["active"] = active
        # Keep status consistent unless explicitly provided
        if status is None:
            if active and grp.get("status") != "deleted":
                grp["status"] = "active"
            elif (not active) and grp.get("status") != "deleted":
                grp["status"] = "inactive"

    if custom_fields is not None:
        grp["custom_fields"] = custom_fields

    if status is not None:
        grp["status"] = status
        if status == "deleted":
            grp["active"] = False

    grp["updated_at"] = now

    _save("people_and_groups.json", pag)

    _log_event(events, account_id, "update_group", params, "succeeded",
               affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
    _save("integration_events.json", events)

    return {"data": grp}

def get_all_requester_groups(account_id, workspace_id=None, status=None, group_visibility=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_urlsafe(12).replace('-','').replace('_','')}"[:28]

    def _log_event(events, acct_id, tool, params, status_, err=None, affected_collection=None, affected_id=None, vendor_id=None, http_method=None, endpoint=None, duration_ms=None):
        ev = {
            "id": _new_id("fse"),
            "account_id": acct_id if acct_id is not None else "fsa_unknown",
            "tool_name": tool,
            "request_params": params if isinstance(params, dict) else {},
            "http_method": http_method,
            "endpoint": endpoint,
            "status": "queued",
            "error_message": None,
            "affected_collection": affected_collection,
            "affected_id": affected_id,
            "vendor_freshservice_id": vendor_id,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        ev["status"] = status_
        if err:
            ev["error_message"] = err
        if duration_ms is not None:
            ev["duration_ms"] = max(0, int(duration_ms))
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        return ev

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        m = re.fullmatch(r"idx:(\d+)", cur)
        if not m:
            return None
        return int(m.group(1))

    params = {
        "account_id": account_id,
        "workspace_id": workspace_id,
        "status": status,
        "group_visibility": group_visibility,
        "limit": limit,
        "cursor": cursor,
        "sort_by": sort_by,
        "sort_order": sort_order,
    }

    events = _load("integration_events.json")

    # Validate
    if not isinstance(account_id, str) or not re.fullmatch(r"^fsa_[0-9A-Za-z]+$", account_id):
        _log_event(events, account_id if isinstance(account_id, str) else None, "get_all_requester_groups",
                   params, "failed", err="Invalid account_id", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "account_id is invalid", field="account_id")

    if workspace_id is not None and not isinstance(workspace_id, int):
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="Invalid workspace_id", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "workspace_id must be integer", field="workspace_id")

    if status is not None and status not in ("active", "inactive", "deleted"):
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="Invalid status", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    if group_visibility is not None and group_visibility not in ("manual", "dynamic"):
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="Invalid group_visibility", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "group_visibility is invalid", field="group_visibility")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="Invalid limit", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    idx = _parse_cursor(cursor)
    if idx is None or idx < 0:
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="Invalid cursor", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at", "name", "freshservice_id"):
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="Invalid sort_by", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "sort_by is invalid", field="sort_by")

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="Invalid sort_order", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "sort_order is invalid", field="sort_order")

    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="No active account context", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("UNAUTHORIZED", "No active account available for this operation")

    # RATE LIMIT (tenant-level): 120 requests per rolling 60 seconds per account across all tools
    window_s = 60
    limit_per_window = 120
    now_dt = datetime.datetime.utcnow()
    recent = 0
    for ev in events:
        if ev.get("account_id") != account_id:
            continue
        ts = ev.get("created_at")
        if not isinstance(ts, str):
            continue
        try:
            s = ts[:-1] if ts.endswith("Z") else ts
            dt = datetime.datetime.fromisoformat(s)
        except Exception:
            continue
        if (now_dt - dt).total_seconds() <= window_s:
            recent += 1
    if recent >= limit_per_window:
        _log_event(events, account_id, "get_all_requester_groups", params, "failed",
                   err="Rate limit exceeded", affected_collection="people_and_groups",
                   duration_ms=(time.time()-t0)*1000)
        _save("integration_events.json", events)
        return _err("RATE_LIMIT", "Too many requests", retry_after_seconds=window_s)

    pag = _load("people_and_groups.json")
    rows = [r for r in pag if r.get("account_id") == account_id and r.get("entity_type") == "group" and r.get("group_kind") == "requester_group"]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if group_visibility is not None:
        rows = [r for r in rows if r.get("group_visibility") == group_visibility]
    if workspace_id is not None:
        # workspace_id is not a first-class field on people_and_groups; allow filtering via custom_fields/raw schema cache if present.
        def _match_ws(r):
            cf = r.get("custom_fields")
            if isinstance(cf, dict) and cf.get("workspace_id") == workspace_id:
                return True
            return False
        rows = [r for r in rows if _match_ws(r)]

    def _key(r):
        v = r.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort_by == "name":
            return (v or "").lower() if isinstance(v, str) else ""
        if sort_by == "freshservice_id":
            return v if isinstance(v, int) else -1
        return v

    reverse = (sort_order == "desc")
    rows_sorted = sorted(rows, key=_key, reverse=reverse)

    total = len(rows_sorted)
    page = rows_sorted[idx: idx + limit]
    next_idx = idx + len(page)
    has_more = next_idx < total
    next_cursor = f"idx:{next_idx}" if has_more else None

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": f"idx:{idx}",
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
        }
    }

    _log_event(events, account_id, "get_all_requester_groups", params, "succeeded",
               affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
    _save("integration_events.json", events)
    return resp

def get_requester_groups_by_id(account_id, group_ids, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    events = _load("integration_events.json")
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_event_id():
        # deterministic-ish, collision resistant enough for local json store
        return "fse_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")

    def _append_event(account_row, tool_name, request_params, status, error_message=None, affected_collection=None, affected_id=None, vendor_freshservice_id=None, http_method=None, endpoint=None, duration_ms=None):
        ev = {
            "id": _new_event_id(),
            "account_id": account_row["id"] if account_row else (account_id if isinstance(account_id, str) else "unknown"),
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "http_method": http_method,
            "endpoint": endpoint,
            "status": "queued",
            "error_message": None,
            "affected_collection": None,
            "affected_id": None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        # transition exactly once
        ev["status"] = status
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ev["error_message"] = error_message
        ev["affected_collection"] = affected_collection
        ev["affected_id"] = affected_id
        ev["vendor_freshservice_id"] = vendor_freshservice_id
        ev["http_method"] = http_method
        ev["endpoint"] = endpoint
        ev["duration_ms"] = int(duration_ms) if isinstance(duration_ms, (int, float)) and duration_ms >= 0 else max(0, int(duration_ms)) if isinstance(duration_ms, (int, float)) else 0
        _save("integration_events.json", events)

    # Validate input
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Za-z]+$", account_id):
        # try to find an active account for logging; if none, log to provided/unknown
        accounts = _load("fs_accounts.json")
        active_any = next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(active_any, "get_requester_groups_by_id", {"account_id": account_id, "group_ids": group_ids}, "failed",
                      error_message="Invalid account_id.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "Invalid account_id.")
    if not isinstance(group_ids, list) or len(group_ids) < 1:
        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if acct is None or acct.get("status") != "active":
            acct_for_log = next((a for a in accounts if a.get("status") == "active"), None)
        else:
            acct_for_log = acct
        _append_event(acct_for_log, "get_requester_groups_by_id", {"account_id": account_id, "group_ids": group_ids}, "failed",
                      error_message="group_ids must be a non-empty array.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "group_ids must be a non-empty array.")
    bad = [gid for gid in group_ids if (not isinstance(gid, str) or not re.match(r"^fsp_[0-9A-Za-z]+$", gid))]
    if bad:
        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        acct_for_log = acct if (acct and acct.get("status") == "active") else next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(acct_for_log, "get_requester_groups_by_id", {"account_id": account_id, "group_ids": group_ids}, "failed",
                      error_message="One or more group_ids are malformed.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "One or more group_ids are malformed.", invalid_ids=bad)

    # Resolve tenant / authorization (ambient auth): must associate to exactly one active fs_accounts row
    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
