        ev["endpoint"] = endpoint
        ev["duration_ms"] = int(duration_ms) if isinstance(duration_ms, (int, float)) and duration_ms >= 0 else max(0, int(duration_ms)) if isinstance(duration_ms, (int, float)) else 0
        _save("integration_events.json", events)

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Za-z]+$", account_id):
        accounts = _load("fs_accounts.json")
        active_any = next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(active_any, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
                      "failed", error_message="Invalid account_id.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "Invalid account_id.")
    if not isinstance(name, str) or not name.strip():
        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(acct, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
                      "failed", error_message="Invalid name.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if group_visibility is not None:
        if not isinstance(group_visibility, str) or group_visibility not in ("manual", "dynamic"):
            accounts = _load("fs_accounts.json")
            acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
            _append_event(acct, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
