        _append_event(acct, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
                      "failed", error_message="Invalid active.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "active must be boolean.")
    if custom_fields is not None and not isinstance(custom_fields, dict):
        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(acct, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
                      "failed", error_message="Invalid custom_fields.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "custom_fields must be an object.")

    # Resolve tenant / authorization
    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        acct_for_log = next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(acct_for_log, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
