                          "failed", error_message="Parent is not a group.", affected_collection="people_and_groups", affected_id=parent_group_id, duration_ms=(time.time()-t0)*1000)
            return _err("NOT_FOUND", "parent_group_id does not refer to a group.")
        if parent.get("status") == "deleted":
