                          "failed", error_message="Parent group is deleted.", affected_collection="people_and_groups", affected_id=parent_group_id, duration_ms=(time.time()-t0)*1000)
            return _err("CONFLICT", "Cannot parent under a deleted group.")

    # Name conflict check (requester groups, not deleted)
    norm = name.strip().casefold()
    for r in pg:
        if r.get("account_id") != account_id:
            continue
        if r.get("entity_type") != "group" or r.get("group_kind") != "requester_group":
            continue
        if r.get("status") == "deleted":
            continue
        if isinstance(r.get("name"), str) and r["name"].strip().casefold() == norm:
            _append_event(acct, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
