            return _err("CONFLICT", "A requester group with the same name already exists in the tenant.", existing_id=r.get("id"))

    # Create group
    new_row = {
        "id": _new_id("fsp"),
        "account_id": account_id,
        "entity_type": "group",
        "freshservice_id": None,
        "group_kind": "requester_group",
        "group_visibility": group_visibility if group_visibility is not None else "manual",
