        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    # If parent_group_id is meant to attach hierarchy for groups, store it in parent_group_id field
    if parent_group_id is not None:
        new_row["parent_group_id"] = parent_group_id

    # constraints: check group_kind when entity_type='group'
    if new_row["group_kind"] not in ("agent_group", "requester_group"):
        _append_event(acct, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
                      "failed", error_message="Invalid group_kind.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "Invalid group_kind for group.")

    pg.append(new_row)
    _save("people_and_groups.json", pg)

    _append_event(acct, "create_requester_group", {"account_id": account_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields},
                  "succeeded", affected_collection="people_and_groups", affected_id=new_row["id"], vendor_freshservice_id=None, duration_ms=(time.time()-t0)*1000)
    return {"requester_group": new_row}

