            _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                          "failed", error_message="Group cannot parent itself.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("VALIDATION_ERROR", "parent_group_id cannot be the group itself.")
        parent = next((r for r in pg if r.get("id") == parent_group_id and r.get("account_id") == account_id), None)
        if not parent:
            _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                          "failed", error_message="Parent group not found.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("NOT_FOUND", "parent_group_id does not exist in the tenant.")
        if parent.get("entity_type") != "group":
            _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                          "failed", error_message="Parent is not a group.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("NOT_FOUND", "parent_group_id does not refer to a group.")
        if parent.get("status") == "deleted":
            _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                          "failed", error_message="Parent group deleted.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("CONFLICT", "Cannot parent under a deleted group.")

    # group_visibility change support: forbid change once set if it would break membership rules
    if group_visibility is not None:
        # in this integration, we disallow changing visibility at all (common vendor restriction)
        if isinstance(row.get("group_visibility"), str) and row.get("group_visibility") != group_visibility:
            _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                          "failed", error_message="Changing group_visibility is not supported.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("VALIDATION_ERROR", "Changing group_visibility is not supported for existing requester groups.")

    # Status transition enforcement (people_and_groups lifecycle)
    if status is not None:
        cur = row.get("status")
        transitions = {
            "active": {"inactive", "deleted"},
            "inactive": {"active", "deleted"},
            "deleted": set(),
        }
        if cur not in transitions:
            _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                          "failed", error_message="Current status invalid.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("CONFLICT", "Current record status is invalid.")
        if status != cur and status not in transitions[cur]:
            _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                          "failed", error_message="Illegal status transition.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("INVALID_TRANSITION", f"Illegal status transition from '{cur}' to '{status}'.")

    # Name conflict check if changing name
    if name is not None:
        norm = name.strip().casefold()
        for r in pg:
            if r.get("account_id") != account_id:
                continue
            if r.get("id") == group_id:
                continue
            if r.get("entity_type") != "group" or r.get("group_kind") != "requester_group":
                continue
            if r.get("status") == "deleted":
                continue
            if isinstance(r.get("name"), str) and r["name"].strip().casefold() == norm:
                _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                              "failed", error_message="Requester group with same name already exists.", affected_collection="people_and_groups", affected_id=r.get("id"), duration_ms=(time.time()-t0)*1000)
                return _err("CONFLICT", "A requester group with the same name already exists in the tenant.", existing_id=r.get("id"))

    # Apply updates
    changed = False
    if name is not None:
        row["name"] = name.strip()
        changed = True
    if parent_group_id is not None:
        row["parent_group_id"] = parent_group_id
        changed = True
    if active is not None:
        row["active"] = active
        changed = True
    if custom_fields is not None:
        row["custom_fields"] = custom_fields
        changed = True
    if status is not None and status != row.get("status"):
        row["status"] = status
        changed = True

    if not changed:
        # no-op should not report success without effect
        _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                      "failed", error_message="No changes requested.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "No changes requested.")

    row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    pg[idx] = row
    _save("people_and_groups.json", pg)

    _append_event(acct, "update_requester_group", {"account_id": account_id, "group_id": group_id, "name": name, "group_visibility": group_visibility, "parent_group_id": parent_group_id, "active": active, "custom_fields": custom_fields, "status": status},
                  "succeeded", affected_collection="people_and_groups", affected_id=group_id, vendor_freshservice_id=row.get("freshservice_id"), duration_ms=(time.time()-t0)*1000)
    return {"requester_group": row}

def list_requester_group_members(account_id, group_id, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    events = _load("integration_events.json")
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + "_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")

    def _append_event(account_row, tool_name, request_params, status_out, error_message=None, affected_collection=None, affected_id=None, vendor_freshservice_id=None, http_method=None, endpoint=None, duration_ms=None):
        ev = {
            "id": _new_id("fse"),
            "account_id": account_row["id"] if account_row else (account_id if isinstance(account_id, str) else "unknown"),
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "http_method": http_method,
            "endpoint": endpoint,
            "status": "queued",
            "error_message": None,
            "affected_collection": None,
            "affected_id": None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        ev["status"] = status_out
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ev["error_message"] = error_message
        ev["affected_collection"] = affected_collection
        ev["affected_id"] = affected_id
        ev["vendor_freshservice_id"] = vendor_freshservice_id
        ev["http_method"] = http_method
        ev["endpoint"] = endpoint
        ev["duration_ms"] = int(duration_ms) if isinstance(duration_ms, (int, float)) and duration_ms >= 0 else max(0, int(duration_ms)) if isinstance(duration_ms, (int, float)) else 0
        _save("integration_events.json", events)

    # Basic per-tenant rate limit: 120 calls / 60 seconds (enforced via integration_events)
    def _rate_limited(acct_id):
        # Count events created in last 60 seconds for this account
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for ev in events:
            if ev.get("account_id") != acct_id:
                continue
            ts = ev.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", ""))
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt >= 120, cnt

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Za-z]+$", account_id):
        accounts = _load("fs_accounts.json")
        active_any = next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(active_any, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                      "failed", error_message="Invalid account_id.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "Invalid account_id.")
    if not isinstance(group_id, str) or not re.match(r"^fsp_[0-9A-Za-z]+$", group_id):
        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                      "failed", error_message="Invalid group_id.", affected_collection="people_and_groups", duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "Invalid group_id.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            accounts = _load("fs_accounts.json")
            acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
            _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                          "failed", error_message="Invalid limit.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                      "failed", error_message="Invalid cursor.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "name", "email", "freshservice_id"):
            accounts = _load("fs_accounts.json")
            acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
            _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                          "failed", error_message="Invalid sort_by.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("VALIDATION_ERROR", "Invalid sort_by.")
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
            accounts = _load("fs_accounts.json")
            acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
            _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                          "failed", error_message="Invalid sort_order.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("VALIDATION_ERROR", "Invalid sort_order.")

    # Resolve tenant / authorization
    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        acct_for_log = next((a for a in accounts if a.get("status") == "active"), None)
        _append_event(acct_for_log, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                      "failed", error_message="No active account for tenant.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
        return _err("UNAUTHORIZED", "Caller cannot access the tenant (no active account).")

    limited, count = _rate_limited(account_id)
    if limited:
        _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                      "failed", error_message="Rate limit exceeded.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
        return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=60, limit=120, recent_requests=count)

    pg = _load("people_and_groups.json")

    grp = next((r for r in pg if r.get("id") == group_id and r.get("account_id") == account_id), None)
    if not grp or grp.get("entity_type") != "group" or grp.get("group_kind") != "requester_group":
        _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                      "failed", error_message="Group not found or not a requester group.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
        return _err("NOT_FOUND", "The group does not exist or is not a requester group.")
    if grp.get("status") == "deleted":
        _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                      "failed", error_message="Group is deleted.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
        return _err("NOT_FOUND", "The group does not exist or is not a requester group.")

    # Collect membership edges and requester rows
    edges = [r for r in pg if r.get("account_id") == account_id and r.get("entity_type") == "group_member" and r.get("parent_group_id") == group_id and r.get("status") != "deleted"]
    req_by_id = {r.get("id"): r for r in pg if r.get("account_id") == account_id and r.get("entity_type") == "requester" and r.get("status") != "deleted"}

    members = []
    for e in edges:
        mid = e.get("member_person_id")
        m = req_by_id.get(mid)
        if not m:
            continue
        members.append(m)

    # Sorting
    sort_by_eff = sort_by if sort_by is not None else "created_at"
    sort_order_eff = sort_order if sort_order is not None else "asc"

    def _k(r):
        v = r.get(sort_by_eff)
        if sort_by_eff in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort_by_eff == "freshservice_id":
            return v if isinstance(v, int) else -1
        if isinstance(v, str):
            return v.casefold()
        return ""

    members.sort(key=_k, reverse=(sort_order_eff == "desc"))

    # Cursor pagination: cursor is base64 of integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                          "failed", error_message="Invalid cursor encoding.", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    lim = limit if limit is not None else 50
    page = members[offset:offset + lim]
    next_off = offset + lim
    has_more = next_off < len(members)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("ascii").rstrip("=")

    _append_event(acct, "list_requester_group_members", {"account_id": account_id, "group_id": group_id, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                  "succeeded", affected_collection="people_and_groups", affected_id=group_id, duration_ms=(time.time()-t0)*1000)
    return {
        "members": page,
        "meta": {
            "total": len(members),
            "limit": lim,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by_eff,
            "sort_order": sort_order_eff,
        },
    }

def get_all_canned_response(account_id, workspace_id=None, folder_id=None, status=None, search=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Prepare queued event (must always be appended)
    events = _load("integration_events.json")
    def _new_event_id():
        # deterministic enough for local store
        return "evt_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")

    event = {
        "id": _new_event_id(),
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "get_all_canned_response",
        "request_params": {
            "account_id": account_id,
            "workspace_id": workspace_id,
            "folder_id": folder_id,
            "status": status,
            "search": search,
            "limit": limit,
            "cursor": cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
        "http_method": "GET",
        "endpoint": "/api/v2/canned_responses",
        "status": "queued",
        "error_message": None,
        "affected_collection": "catalog_and_kb",
        "affected_id": None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    events.append(event)
    _save("integration_events.json", events)

    def _finalize_ok(payload):
        events2 = _load("integration_events.json")
        for e in events2:
            if e.get("id") == event["id"]:
                e["status"] = "succeeded"
                e["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("integration_events.json", events2)
        return payload

    def _finalize_err(code, msg, **x):
        events2 = _load("integration_events.json")
        for e in events2:
            if e.get("id") == event["id"]:
                e["status"] = "failed"
                e["error_message"] = msg
                e["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("integration_events.json", events2)
        return _err(code, msg, **x)

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        return _finalize_err("VALIDATION_ERROR", "Invalid account_id format.", field="account_id")
    if workspace_id is not None and not isinstance(workspace_id, int):
        return _finalize_err("VALIDATION_ERROR", "workspace_id must be an integer.", field="workspace_id")
    if folder_id is not None:
        if not isinstance(folder_id, str) or not re.match(r"^fsx_[A-Za-z0-9]+$", folder_id):
            return _finalize_err("VALIDATION_ERROR", "Invalid folder_id format.", field="folder_id")
    allowed_status = {"active", "archived", "deleted", "draft", "published"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _finalize_err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(list(allowed_status)))
    if search is not None and not isinstance(search, str):
        return _finalize_err("VALIDATION_ERROR", "search must be a string.", field="search")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _finalize_err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    allowed_sort_by = {"created_at", "updated_at", "name", "freshservice_id"}
    if sort_by is None:
        sort_by = "updated_at"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        return _finalize_err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by", allowed=sorted(list(allowed_sort_by)))
    allowed_sort_order = {"asc", "desc"}
    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
        return _finalize_err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order", allowed=sorted(list(allowed_sort_order)))
    if cursor is not None and not isinstance(cursor, str):
        return _finalize_err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

