        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_urlsafe(18).replace('-','').replace('_','')}"[:32]

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return "BAD"
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "BAD"
            idx = obj.get("idx")
            if not isinstance(idx, int) or idx < 0:
                return "BAD"
            return idx
        except Exception:
            return "BAD"

    def _encode_cursor(idx):
        raw = json.dumps({"idx": idx}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _finalize_event(ev_id, statusv, error_message=None, t0=None, affected_id=None):
        events2 = _load("integration_events.json")
