                r["status"] = statusv
                r["error_message"] = error_message
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000)) if isinstance(t0, (int, float)) else 0
                r["updated_at"] = _utcnow_z()
                if affected_id is not None:
                    r["affected_id"] = affected_id
                break
        _save("integration_events.json", events2)

    t0 = time.time()
    now = _utcnow_z()

    ev_id = _new_id("fse")
    params = {
        "account_id": account_id,
        "solution_category_id": solution_category_id,
        "limit": limit,
        "cursor": cursor,
        "sort_by": sort_by,
        "sort_order": sort_order,
        "status": status,
    }
    events = _load("integration_events.json")
    events.append(
        {
            "id": ev_id,
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "get_list_of_solution_folder",
            "request_params": params,
            "http_method": "GET",
            "endpoint": "/solutions/folders",
            "status": "queued",
            "error_message": None,
            "affected_collection": "catalog_and_kb",
            "affected_id": solution_category_id if isinstance(solution_category_id, str) else None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
    )
    _save("integration_events.json", events)

    try:
        if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]+$", account_id):
            _finalize_event(ev_id, "failed", "Invalid account_id.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
