            return _err("VALIDATION_ERROR", "Invalid solution_category_id.", field="solution_category_id")
        if limit is None:
            limit = 25
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _finalize_event(ev_id, "failed", "limit must be between 1 and 100.", t0=t0)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")
        if sort_by is None:
