        folders = [r for r in rows if r.get("account_id") == account_id and r.get("entity_type") == "solution_folder" and r.get("parent_id") == solution_category_id]
        if status is not None:
            folders = [r for r in folders if r.get("status") == status]

        def _k(r):
            v = r.get(sort_by)
            return "" if v is None else v

        folders.sort(key=_k, reverse=(sort_order == "desc"))

