                   {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                   "failed", err="Invalid name")
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if body is not None and (not isinstance(body, str) or not body.strip()):
        events = _load("integration_events.json")
        _log_event(events, account_id, "update_solution_article",
                   {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                   "failed", err="Invalid body")
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "body must be a non-empty string")

    pub_iso = _parse_dt(published_at)
    if pub_iso == "BAD":
        events = _load("integration_events.json")
        _log_event(events, account_id, "update_solution_article",
                   {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                   "failed", err="Invalid published_at")
        _save("integration_events.json", events)
        return _err("VALIDATION_ERROR", "published_at must be a valid RFC3339 date-time")

    # Auth
    accounts = _load("fs_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    events = _load("integration_events.json")
    if acct is None:
        _log_event(events, account_id, "update_solution_article",
                   {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                   "failed", err="No active account", affected_collection="fs_accounts")
        _save("integration_events.json", events)
        return _err("UNAUTHORIZED", "No active account available for this request")

    cak = _load("catalog_and_kb.json")
    idx = None
    for i, r in enumerate(cak):
        if r.get("id") == solution_article_id and r.get("account_id") == account_id and r.get("entity_type") == "solution_article":
            idx = i
            break
    if idx is None:
        _log_event(events, account_id, "update_solution_article",
                   {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                   "failed", err="Article not found", affected_collection="catalog_and_kb", affected_id=solution_article_id)
        _save("integration_events.json", events)
        return _err("NOT_FOUND", "Solution article not found")

    art = cak[idx]

    # FORBIDDEN mapping: if restricted, disallow edits (no caller context)
    if art.get("visibility") == "restricted":
        _log_event(events, account_id, "update_solution_article",
                   {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                   "failed", err="Forbidden by visibility rules", affected_collection="catalog_and_kb", affected_id=solution_article_id,
                   vendor_id=art.get("freshservice_id"))
        _save("integration_events.json", events)
        return _err("UNAUTHORIZED", "Forbidden")

    if art.get("status") == "deleted":
        _log_event(events, account_id, "update_solution_article",
                   {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                   "failed", err="Cannot update deleted article", affected_collection="catalog_and_kb", affected_id=solution_article_id,
                   vendor_id=art.get("freshservice_id"))
        _save("integration_events.json", events)
        return _err("INVALID_TRANSITION", "Cannot update a deleted solution article")

    # If moving folder, validate target folder exists and is solution_folder
    if solution_folder_id is not None and solution_folder_id != art.get("parent_id"):
        folder = next((r for r in cak if r.get("id") == solution_folder_id and r.get("account_id") == account_id and r.get("entity_type") == "solution_folder" and r.get("status") != "deleted"), None)
        if folder is None:
            _log_event(events, account_id, "update_solution_article",
                       {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                       "failed", err="Target folder not found", affected_collection="catalog_and_kb", affected_id=solution_folder_id)
            _save("integration_events.json", events)
            return _err("NOT_FOUND", "Target solution folder not found")
        art["parent_id"] = solution_folder_id
        # If workspace_id not explicitly set, keep as-is (do not inherit)

    # Lifecycle transition enforcement
    transitions = {
        "active": {"archived", "deleted"},
        "archived": {"active", "deleted"},
        "draft": {"published", "deleted"},
        "published": {"draft", "deleted"},
        "deleted": set(),
    }
    if status is not None and status != art.get("status"):
        cur = art.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log_event(events, account_id, "update_solution_article",
                       {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
                       "failed", err=f"Illegal status transition {cur}->{status}", affected_collection="catalog_and_kb", affected_id=solution_article_id,
                       vendor_id=art.get("freshservice_id"))
            _save("integration_events.json", events)
            return _err("INVALID_TRANSITION", f"Illegal status transition from {cur} to {status}")
        art["status"] = status
        if status == "published" and (pub_iso is None and not art.get("published_at")):
            art["published_at"] = now_iso

    # Apply partial updates
    if workspace_id is not None:
        art["workspace_id"] = workspace_id
    if name is not None:
        art["name"] = name
    if description is not None:
        art["description"] = description
    if body is not None:
        art["body"] = body
    if tags is not None:
        art["tags"] = tags
    if visibility is not None:
        art["visibility"] = visibility
    if draft is not None:
        art["draft"] = bool(draft)
    if published_at is not None:
        art["published_at"] = pub_iso
    if raw_payload is not None:
        art["raw_payload"] = raw_payload

    art["updated_at"] = now_iso
    cak[idx] = art
    _save("catalog_and_kb.json", cak)

    _log_event(events, account_id, "update_solution_article",
               {"account_id": account_id, "solution_article_id": solution_article_id, "solution_folder_id": solution_folder_id, "workspace_id": workspace_id, "name": name, "description": description, "body": body, "tags": tags, "visibility": visibility, "draft": draft, "published_at": published_at, "status": status, "raw_payload": raw_payload},
               "succeeded", affected_collection="catalog_and_kb", affected_id=solution_article_id, vendor_id=art.get("freshservice_id"))
    _save("integration_events.json", events)

    return {"article": art}

def create_solution_folder(account_id, solution_category_id, name, workspace_id=None, description=None, visibility=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_urlsafe(18).replace('-','').replace('_','')}"[:32]

    def _finalize_event(ev_id, statusv, error_message=None, affected_id=None, vendor_id=None, t0=None):
        events2 = _load("integration_events.json")
        for r in events2:
            if r.get("id") == ev_id and r.get("status") == "queued":
                r["status"] = statusv
                r["error_message"] = error_message
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000)) if isinstance(t0, (int, float)) else 0
                r["updated_at"] = _utcnow_z()
                if affected_id is not None:
                    r["affected_id"] = affected_id
                if vendor_id is not None:
                    r["vendor_freshservice_id"] = vendor_id
                break
        _save("integration_events.json", events2)

    t0 = time.time()
    now = _utcnow_z()

    params = {
        "account_id": account_id,
        "solution_category_id": solution_category_id,
        "workspace_id": workspace_id,
        "name": name,
        "description": description,
        "visibility": visibility,
    }

    ev_id = _new_id("fse")
    events = _load("integration_events.json")
    events.append(
        {
            "id": ev_id,
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "create_solution_folder",
            "request_params": params,
            "http_method": "POST",
            "endpoint": "/solutions/folders",
            "status": "queued",
            "error_message": None,
            "affected_collection": "catalog_and_kb",
            "affected_id": None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
    )
    _save("integration_events.json", events)

    try:
        if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]{3,}$", account_id):
            _finalize_event(ev_id, "failed", "Invalid account_id.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
        if not isinstance(solution_category_id, str) or not re.match(r"^fsx_[0-9A-Z]{3,}$", solution_category_id):
            _finalize_event(ev_id, "failed", "Invalid solution_category_id.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid solution_category_id.", field="solution_category_id")
        if not isinstance(name, str) or not name.strip():
            _finalize_event(ev_id, "failed", "name is required.", t0=t0)
            return _err("VALIDATION_ERROR", "name is required.", field="name")
        if workspace_id is not None and not isinstance(workspace_id, int):
            _finalize_event(ev_id, "failed", "workspace_id must be integer.", t0=t0)
            return _err("VALIDATION_ERROR", "workspace_id must be integer.", field="workspace_id")
        if description is not None and not isinstance(description, str):
            _finalize_event(ev_id, "failed", "description must be string.", t0=t0)
            return _err("VALIDATION_ERROR", "description must be string.", field="description")
        if visibility is not None and visibility not in ("public", "logged_in_users", "agents_only", "restricted"):
            _finalize_event(ev_id, "failed", "Invalid visibility.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid visibility.", field="visibility")

        accounts = _load("fs_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if not acct:
            _finalize_event(ev_id, "failed", "Account not found.", t0=t0)
            return _err("NOT_FOUND", "Account not found.", account_id=account_id)
        if acct.get("status") != "active":
            _finalize_event(ev_id, "failed", "Account is not active.", t0=t0)
            return _err("UNAUTHORIZED", "Account is not active.", account_id=account_id, status=acct.get("status"))

        rows = _load("catalog_and_kb.json")
        parent = next((r for r in rows if r.get("id") == solution_category_id and r.get("account_id") == account_id and r.get("entity_type") == "solution_category"), None)
        if not parent:
            _finalize_event(ev_id, "failed", "Solution category not found.", t0=t0)
            return _err("NOT_FOUND", "Solution category not found.", solution_category_id=solution_category_id)

        row_id = _new_id("fsx")
        while any(r.get("id") == row_id for r in rows):
            row_id = _new_id("fsx")

        used_vendor_ids = {r.get("freshservice_id") for r in rows if r.get("account_id") == account_id and r.get("entity_type") == "solution_folder" and isinstance(r.get("freshservice_id"), int)}
        vendor_id = max(used_vendor_ids) + 1 if used_vendor_ids else 1
        if any(r.get("account_id") == account_id and r.get("entity_type") == "solution_folder" and r.get("freshservice_id") == vendor_id for r in rows):
            _finalize_event(ev_id, "failed", "Vendor id conflict.", t0=t0)
            return _err("CONFLICT", "Vendor id conflict (please retry).")

        row = {
            "id": row_id,
            "account_id": account_id,
            "entity_type": "solution_folder",
            "freshservice_id": vendor_id,
            "parent_id": solution_category_id,
            "workspace_id": workspace_id,
            "name": name,
            "description": description,
            "body": None,
            "tags": None,
            "visibility": visibility,
            "draft": None,
            "published_at": None,
            "raw_payload": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        rows.append(row)
        _save("catalog_and_kb.json", rows)
        _finalize_event(ev_id, "succeeded", affected_id=row_id, vendor_id=vendor_id, t0=t0)
        return {"folder": row}
    except Exception as e:
        _finalize_event(ev_id, "failed", f"Unexpected error: {type(e).__name__}", t0=t0)
        return _err("CONFLICT", "Unexpected error occurred.", detail=f"{type(e).__name__}")

def update_solution_folder(account_id, solution_folder_id, workspace_id=None, name=None, description=None, visibility=None, status=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    events = _load("integration_events.json")
    accounts = _load("fs_accounts.json")
    ckb = _load("catalog_and_kb.json")

    ev = {
        "id": "fse_" + secrets.token_hex(8).upper(),
        "account_id": account_id if isinstance(account_id, str) else None,
        "tool_name": "update_solution_folder",
        "request_params": {
            "account_id": account_id,
            "solution_folder_id": solution_folder_id,
            "workspace_id": workspace_id,
            "name": name,
            "description": description,
            "visibility": visibility,
            "status": status,
        },
        "http_method": "PATCH",
        "endpoint": "/solutions/folders/{id}",
        "status": "queued",
        "error_message": None,
        "affected_collection": "catalog_and_kb",
        "affected_id": solution_folder_id if isinstance(solution_folder_id, str) else None,
        "vendor_freshservice_id": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    events.append(ev)
    _save("integration_events.json", events)

    def _finish_success(row):
        ev["status"] = "succeeded"
        ev["affected_id"] = row.get("id")
        ev["vendor_freshservice_id"] = row.get("freshservice_id")
        ev["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("integration_events.json", events)
        return {"solution_folder": row}

    def _finish_fail(code, msg, **x):
        ev["status"] = "failed"
        ev["error_message"] = msg
        ev["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("integration_events.json", events)
        return _err(code, msg, **x)

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]{3,}$", account_id):
        return _finish_fail("VALIDATION_ERROR", "Malformed account_id.")
    if not isinstance(solution_folder_id, str) or not re.match(r"^fsx_[0-9A-Z]{3,}$", solution_folder_id):
        return _finish_fail("VALIDATION_ERROR", "Malformed solution_folder_id.")
    if workspace_id is not None and not isinstance(workspace_id, int):
        return _finish_fail("VALIDATION_ERROR", "workspace_id must be an integer.")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _finish_fail("VALIDATION_ERROR", "name must be a non-empty string when provided.")
    if description is not None and not isinstance(description, str):
        return _finish_fail("VALIDATION_ERROR", "description must be a string.")
    allowed_vis = {"public", "logged_in_users", "agents_only", "restricted"}
    if visibility is not None:
        if not isinstance(visibility, str) or visibility not in allowed_vis:
            return _finish_fail("VALIDATION_ERROR", "visibility must be one of: public, logged_in_users, agents_only, restricted.")
    allowed_status = {"active", "archived", "deleted", "draft", "published"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _finish_fail("VALIDATION_ERROR", "status must be one of: active, archived, deleted, draft, published.")

    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        return _finish_fail("UNAUTHORIZED", "No active Freshservice account available for this request.")

    row = next((r for r in ckb if r.get("id") == solution_folder_id and r.get("account_id") == account_id and r.get("entity_type") == "solution_folder"), None)
    if not row:
        return _finish_fail("NOT_FOUND", "Solution folder not found for this account.")

    # Lifecycle transition enforcement
    if status is not None:
        current = row.get("status")
        transitions = {
            "active": ["archived", "deleted"],
            "archived": ["active", "deleted"],
            "draft": ["published", "deleted"],
            "published": ["draft", "deleted"],
            "deleted": [],
        }
        if current not in transitions:
            return _finish_fail("VALIDATION_ERROR", "Current folder status is invalid.")
        if status != current and status not in transitions[current]:
            return _finish_fail("INVALID_TRANSITION", f"Illegal status transition from '{current}' to '{status}'.")

    # Apply updates
    changed = False
    if workspace_id is not None and row.get("workspace_id") != workspace_id:
        row["workspace_id"] = workspace_id
        changed = True
    if name is not None and row.get("name") != name.strip():
        row["name"] = name.strip()
        changed = True
    if description is not None and row.get("description") != description:
        row["description"] = description
        changed = True
    if visibility is not None and row.get("visibility") != visibility:
        row["visibility"] = visibility
        changed = True
    if status is not None and row.get("status") != status:
        row["status"] = status
        changed = True

    if not changed:
        # Real APIs usually return the resource; this still has effect=none.
        # Enforce "no success without effect" -> treat as conflict-less idempotency? Here it's a mutation with no effect.
        return _finish_fail("CONFLICT", "No changes detected; update would have no effect.")

    row["updated_at"] = now
    _save("catalog_and_kb.json", ckb)
    return _finish_success(row)

