        ev["status"] = "failed"
        ev["error_message"] = msg
        ev["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("integration_events.json", events)
        return _err(code, msg, **x)

    if not isinstance(account_id, str) or not re.match(r"^fsa_[0-9A-Z]{3,}$", account_id):
        return _finish_fail("VALIDATION_ERROR", "Malformed account_id.")
    if not isinstance(solution_article_id, str) or not re.match(r"^fsx_[0-9A-Z]{3,}$", solution_article_id):
        return _finish_fail("VALIDATION_ERROR", "Malformed solution_article_id.")
    if workspace_id is not None and not isinstance(workspace_id, int):
        return _finish_fail("VALIDATION_ERROR", "workspace_id must be an integer.")
    if draft is not None and not isinstance(draft, bool):
        return _finish_fail("VALIDATION_ERROR", "draft must be a boolean.")
    allowed_vis = {"public", "logged_in_users", "agents_only", "restricted"}
    if visibility is not None:
        if not isinstance(visibility, str) or visibility not in allowed_vis:
            return _finish_fail("VALIDATION_ERROR", "visibility must be one of: public, logged_in_users, agents_only, restricted.")
    allowed_status = {"active", "archived", "deleted", "draft", "published"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _finish_fail("VALIDATION_ERROR", "status must be one of: active, archived, deleted, draft, published.")

    pub_dt = None
    if published_at is not None:
        pub_dt = _parse_dt(published_at)
        if pub_dt is None:
            return _finish_fail("VALIDATION_ERROR", "published_at must be an ISO 8601 date-time string.")

    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        return _finish_fail("UNAUTHORIZED", "No active Freshservice account available for this request.")

    row = next((r for r in ckb if r.get("id") == solution_article_id and r.get("account_id") == account_id and r.get("entity_type") == "solution_article"), None)
    if not row:
        return _finish_fail("NOT_FOUND", "Solution article not found for this account.")

    if row.get("status") == "deleted":
        return _finish_fail("INVALID_TRANSITION", "Publishing is forbidden for deleted articles.")

    # If workspace_id provided, enforce match when article has a workspace_id stored
    if workspace_id is not None and row.get("workspace_id") is not None and row.get("workspace_id") != workspace_id:
        return _finish_fail("CONFLICT", "workspace_id does not match the article workspace scope.")

    # Determine target state based on draft flag if provided.
    # Business rule: publish transitions draft->published; if draft==True, keep/set draft.
    desired = None
    if draft is False:
        desired = "published"
    elif draft is True:
        desired = "draft"
    elif status is not None:
        desired = status
    else:
        desired = "published"

    transitions = {
        "active": ["archived", "deleted"],
        "archived": ["active", "deleted"],
        "draft": ["published", "deleted"],
        "published": ["draft", "deleted"],
        "deleted": [],
    }
    current = row.get("status")
    if current not in transitions:
        return _finish_fail("VALIDATION_ERROR", "Current article status is invalid.")

    # Enforce the publish rule: draft->published only, unless explicitly keeping draft.
    if desired == "published":
        if current != "draft":
            # Idempotency: if already published, treat as conflict-less "no-op" is not allowed (no success without effect)
            if current == "published":
                return _finish_fail("CONFLICT", "Article is already published.")
            return _finish_fail("INVALID_TRANSITION", f"Illegal status transition from '{current}' to 'published'.")
    else:
        # For non-publish desired, just enforce lifecycle transitions if status changes
        if desired != current and desired not in transitions[current]:
            return _finish_fail("INVALID_TRANSITION", f"Illegal status transition from '{current}' to '{desired}'.")

    changed = False

    if visibility is not None and row.get("visibility") != visibility:
        row["visibility"] = visibility
        changed = True

    if desired != current:
        row["status"] = desired
        changed = True

    if desired == "published":
        # Set published_at and draft flag
        new_pub = (pub_dt or now_dt).replace(microsecond=0).isoformat() + "Z"
        if row.get("published_at") != new_pub:
            row["published_at"] = new_pub
            changed = True
        if row.get("draft") is not False:
            row["draft"] = False
            changed = True
    elif desired == "draft":
        if row.get("draft") is not True:
            row["draft"] = True
            changed = True

    if workspace_id is not None and row.get("workspace_id") != workspace_id:
        row["workspace_id"] = workspace_id
        changed = True

    if not changed:
        return _finish_fail("CONFLICT", "No changes detected; publish would have no effect.")

    row["updated_at"] = now
    _save("catalog_and_kb.json", ckb)
    return _finish_success(row)

def create_fs_account(freshservice_domain, api_key, default_workspace_id=None, **_extra):
    import json, os, datetime, time, re, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_urlsafe(18).replace('-','').replace('_','')}"[:32]

    def _finalize_event(ev_id, statusv, error_message=None, account_id=None, t0=None):
        events2 = _load("integration_events.json")
        for r in events2:
            if r.get("id") == ev_id and r.get("status") == "queued":
                r["status"] = statusv
                r["error_message"] = error_message
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000)) if isinstance(t0, (int, float)) else 0
                r["updated_at"] = _utcnow_z()
                if account_id is not None:
                    r["account_id"] = account_id
                    r["affected_id"] = account_id
                break
        _save("integration_events.json", events2)

    t0 = time.time()
    now = _utcnow_z()

    params = {
        "freshservice_domain": freshservice_domain,
        "api_key": "***" if isinstance(api_key, str) else api_key,
        "default_workspace_id": default_workspace_id,
    }

    ev_id = _new_id("fse")
    events = _load("integration_events.json")
    events.append(
        {
            "id": ev_id,
            "account_id": None,
            "tool_name": "create_fs_account",
            "request_params": params,
            "http_method": "POST",
            "endpoint": "/accounts",
            "status": "queued",
            "error_message": None,
            "affected_collection": "fs_accounts",
            "affected_id": None,
            "vendor_freshservice_id": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }
    )
    _save("integration_events.json", events)

    try:
        if not isinstance(freshservice_domain, str) or not freshservice_domain.strip():
            _finalize_event(ev_id, "failed", "freshservice_domain is required.", t0=t0)
            return _err("VALIDATION_ERROR", "freshservice_domain is required.", field="freshservice_domain")

        dom = freshservice_domain.strip().lower()
        # Accept "acme" and normalize to "acme.freshservice.com"
        if "." not in dom:
            dom = dom + ".freshservice.com"

        if not (dom.endswith(".freshservice.com") or dom.endswith(".freshworks.com")):
            _finalize_event(ev_id, "failed", "freshservice_domain must end with .freshservice.com or .freshworks.com", t0=t0)
            return _err("VALIDATION_ERROR", "freshservice_domain must end with .freshservice.com or .freshworks.com", field="freshservice_domain")

        if not re.match(r"^[a-z0-9-]+(\.[a-z0-9-]+)*\.(freshservice\.com|freshworks\.com)$", dom):
            _finalize_event(ev_id, "failed", "Invalid freshservice_domain format.", t0=t0)
            return _err("VALIDATION_ERROR", "Invalid freshservice_domain format.", field="freshservice_domain")

        if not isinstance(api_key, str) or len(api_key) < 10:
            _finalize_event(ev_id, "failed", "api_key must be at least 10 characters.", t0=t0)
            return _err("VALIDATION_ERROR", "api_key must be at least 10 characters.", field="api_key")

        if default_workspace_id is not None and not isinstance(default_workspace_id, int):
            _finalize_event(ev_id, "failed", "default_workspace_id must be integer.", t0=t0)
            return _err("VALIDATION_ERROR", "default_workspace_id must be integer.", field="default_workspace_id")

        accounts = _load("fs_accounts.json")
        if any((isinstance(a.get("freshservice_domain"), str) and a.get("freshservice_domain").lower() == dom) for a in accounts):
            _finalize_event(ev_id, "failed", "Account with this domain already exists.", t0=t0)
            return _err("CONFLICT", "Account with this domain already exists.", freshservice_domain=dom)

        # Store a hash only (no plaintext); vendor code uses salted hash, but any one-way hash suffices for datastore
        api_key_hash = hashlib.sha256(api_key.encode("utf-8")).hexdigest()

        account_id = _new_id("fsa")
        while any(a.get("id") == account_id for a in accounts):
            account_id = _new_id("fsa")

        row = {
            "id": account_id,
            "freshservice_domain": dom,
            "api_key_hash": api_key_hash,
            "default_workspace_id": default_workspace_id,
            "status": "active",
            "last_sync_at": None,
            "created_at": now,
            "updated_at": now,
        }
        accounts.append(row)
        _save("fs_accounts.json", accounts)

        _finalize_event(ev_id, "succeeded", account_id=account_id, t0=t0)
        return {"account": row}
    except Exception as e:
        _finalize_event(ev_id, "failed", f"Unexpected error: {type(e).__name__}", t0=t0)
        return _err("CONFLICT", "Unexpected error occurred.", detail=f"{type(e).__name__}")

def update_fs_account(account_id, account, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _hash_key(k):
        # Store a deterministic hash (no plaintext). Use SHA-256.
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    start = time.time()
    ev_id = None

    def _write_event(status, error_message=None, affected_collection=None, affected_id=None, vendor_freshservice_id=None, http_method=None, endpoint=None):
        nonlocal ev_id
        events = _load("integration_events.json")
        now = _now()
        if ev_id is None:
            ev_id = "ev_" + hashlib.sha256((now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:16]
            row = {
                "id": ev_id,
                "account_id": None,  # set once we resolve account
                "tool_name": "update_fs_account",
                "request_params": {"account_id": account_id, "account": account if isinstance(account, dict) else None},
                "http_method": http_method,
                "endpoint": endpoint,
                "status": "queued",
                "error_message": None,
                "affected_collection": affected_collection,
                "affected_id": affected_id,
                "vendor_freshservice_id": vendor_freshservice_id,
                "duration_ms": None,
                "created_at": now,
                "updated_at": now,
            }
            events.append(row)
            _save("integration_events.json", events)

        # update queued -> succeeded/failed exactly once
        events = _load("integration_events.json")
        for r in events:
            if r.get("id") == ev_id:
                if r.get("status") != "queued":
                    # Do not transition again; keep first terminal result.
                    _save("integration_events.json", events)
                    return
                if status not in ("succeeded", "failed"):
                    status = "failed"
                    error_message = "Invalid event status transition attempt."
                r["status"] = status
                r["error_message"] = error_message
                r["affected_collection"] = affected_collection
                r["affected_id"] = affected_id
                r["vendor_freshservice_id"] = vendor_freshservice_id
                r["http_method"] = http_method
                r["endpoint"] = endpoint
                r["duration_ms"] = max(0, int((time.time() - start) * 1000))
                r["updated_at"] = _now()
                _save("integration_events.json", events)
                return
        # if not found, append terminal (shouldn't happen)
        now = _now()
        events.append(
            {
                "id": ev_id,
                "account_id": None,
                "tool_name": "update_fs_account",
                "request_params": {"account_id": account_id, "account": account if isinstance(account, dict) else None},
                "http_method": http_method,
                "endpoint": endpoint,
                "status": status,
                "error_message": error_message,
                "affected_collection": affected_collection,
                "affected_id": affected_id,
                "vendor_freshservice_id": vendor_freshservice_id,
                "duration_ms": max(0, int((time.time() - start) * 1000)),
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("integration_events.json", events)

    # Create queued event first (must be appended for every invocation)
    _write_event("queued")

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fsa_[A-Za-z0-9]+$", account_id):
        _write_event("failed", "Invalid account_id.", affected_collection="fs_accounts", affected_id=str(account_id) if account_id is not None else None)
        return _err("VALIDATION_ERROR", "account_id must match ^fsa_[A-Za-z0-9]+$")

    if not isinstance(account, dict):
        _write_event("failed", "Invalid account object.", affected_collection="fs_accounts", affected_id=account_id)
        return _err("VALIDATION_ERROR", "account must be an object")

    allowed_keys = {"api_key", "default_workspace_id", "status"}
    for k in account.keys():
        if k not in allowed_keys:
            _write_event("failed", f"Unexpected field in account: {k}", affected_collection="fs_accounts", affected_id=account_id)
            return _err("VALIDATION_ERROR", f"Unexpected field in account: {k}")

    if "api_key" in account:
        if not isinstance(account["api_key"], str) or len(account["api_key"]) < 10:
            _write_event("failed", "api_key must be a string with minLength 10.", affected_collection="fs_accounts", affected_id=account_id)
            return _err("VALIDATION_ERROR", "account.api_key must be a string with minLength 10")

    if "default_workspace_id" in account:
        if not isinstance(account["default_workspace_id"], int):
            _write_event("failed", "default_workspace_id must be integer.", affected_collection="fs_accounts", affected_id=account_id)
            return _err("VALIDATION_ERROR", "account.default_workspace_id must be an integer")

    if "status" in account:
        if account["status"] not in ("active", "suspended", "revoked"):
            _write_event("failed", "Invalid status.", affected_collection="fs_accounts", affected_id=account_id)
            return _err("VALIDATION_ERROR", "account.status must be one of: active, suspended, revoked")

    # Load and locate account
    accounts = _load("fs_accounts.json")
    idx = None
    row = None
    for i, r in enumerate(accounts):
        if r.get("id") == account_id:
            idx = i
            row = r
            break
    if row is None:
        _write_event("failed", "Account not found.", affected_collection="fs_accounts", affected_id=account_id)
        return _err("NOT_FOUND", "Freshservice account not found", account_id=account_id)

    # Apply business rules / lifecycle transitions
    current_status = row.get("status")
    if current_status not in ("active", "suspended", "revoked"):
        _write_event("failed", "Stored account status is invalid.", affected_collection="fs_accounts", affected_id=account_id)
        return _err("CONFLICT", "Stored account has invalid status", status=current_status)

    transitions = {
        "active": {"suspended", "revoked"},
        "suspended": {"active", "revoked"},
        "revoked": set(),
    }

    changed = False
    now = _now()

    if "status" in account:
        new_status = account["status"]
        if new_status != current_status:
            if new_status not in transitions.get(current_status, set()):
                _write_event(
                    "failed",
                    f"Illegal status transition {current_status} -> {new_status}.",
                    affected_collection="fs_accounts",
                    affected_id=account_id,
                )
                return _err(
                    "INVALID_TRANSITION",
                    f"Illegal status transition from {current_status} to {new_status}",
                    from_status=current_status,
                    to_status=new_status,
                )
            row["status"] = new_status
            changed = True

    if "default_workspace_id" in account:
        if row.get("default_workspace_id") != account["default_workspace_id"]:
            row["default_workspace_id"] = account["default_workspace_id"]
            changed = True

    if "api_key" in account:
        new_hash = _hash_key(account["api_key"])
        if row.get("api_key_hash") != new_hash:
            row["api_key_hash"] = new_hash
            changed = True

    if not changed:
        # No success without effect for mutations
        _write_event("failed", "No changes applied.", affected_collection="fs_accounts", affected_id=account_id)
        return _err("CONFLICT", "No changes to apply")

    row["updated_at"] = now
    accounts[idx] = row
    _save("fs_accounts.json", accounts)

    _write_event("succeeded", affected_collection="fs_accounts", affected_id=account_id)
    return {"fs_account": row}

def get_current_identity(authorization, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0255000" if __import__("os").path.isdir("./environment_mix/0255000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    start = time.time()
    ev_id = None

    def _write_event(account_id, status, error_message=None):
        nonlocal ev_id
        events = _load("integration_events.json")
        now = _now()

        if ev_id is None:
            ev_id = "ev_" + hashlib.sha256((now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:16]
            events.append(
                {
                    "id": ev_id,
                    "account_id": account_id,
                    "tool_name": "get_current_identity",
                    "request_params": {"authorization": authorization},
                    "http_method": None,
                    "endpoint": None,
                    "status": "queued",
                    "error_message": None,
                    "affected_collection": "fs_accounts",
                    "affected_id": account_id,
                    "vendor_freshservice_id": None,
                    "duration_ms": None,
                    "created_at": now,
                    "updated_at": now,
                }
            )
            _save("integration_events.json", events)

        # update queued -> succeeded/failed exactly once
        events = _load("integration_events.json")
        for r in events:
            if r.get("id") == ev_id:
                if r.get("status") != "queued":
                    _save("integration_events.json", events)
                    return
                r["status"] = status
                r["error_message"] = error_message
                r["duration_ms"] = max(0, int((time.time() - start) * 1000))
                r["updated_at"] = _now()
                _save("integration_events.json", events)
                return
        _save("integration_events.json", events)

    # Validate authorization
    if not isinstance(authorization, str) or not authorization.strip():
        _write_event(None, "failed", "Missing authorization.")
        return _err("VALIDATION_ERROR", "authorization is required")

    token = authorization.strip()
    if token.lower().startswith("bearer "):
        token = token[7:].strip()

    if not token:
        _write_event(None, "failed", "Missing token.")
        return _err("VALIDATION_ERROR", "authorization token is required")

    # Authenticate by matching plaintext against stored hashes is forbidden (no plaintext exists).
    # Therefore, this endpoint can only resolve identities if the caller presents an id-like credential.
    # We treat:
    # - exact fs_accounts.id ("fsa_...") as account selection
    # - freshservice_domain as account selection
    accounts = _load("fs_accounts.json")

    matched = None
    for a in accounts:
        if a.get("id") == token or a.get("freshservice_domain") == token:
            matched = a
            break

    if not matched:
        _write_event(None, "failed", "Invalid credential.")
        return _err("UNAUTHORIZED", "Invalid or unknown credential")

    if matched.get("status") != "active":
        # Business rule: must associate with an active fs_accounts row; fail and write event
        _write_event(matched.get("id"), "failed", "Account is not active.")
        return _err("UNAUTHORIZED", "Account is not active", account_id=matched.get("id"), status=matched.get("status"))

    # Compute basic usage from integration_events
    events = _load("integration_events.json")
    acct_id = matched.get("id")
    total_calls = 0
    total_failed = 0
    total_succeeded = 0
    last_24h = 0
    now_dt = datetime.datetime.utcnow()
    for e in events:
        if e.get("account_id") != acct_id:
            continue
        total_calls += 1
        st = e.get("status")
        if st == "failed":
            total_failed += 1
        elif st == "succeeded":
            total_succeeded += 1
        # last 24h
        ca = e.get("created_at")
        if isinstance(ca, str) and ca.endswith("Z"):
            try:
                dt = datetime.datetime.fromisoformat(ca[:-1])
                if (now_dt - dt).total_seconds() <= 86400:
                    last_24h += 1
            except Exception:
                pass

    _write_event(acct_id, "succeeded", None)

    return {
        "identity": {
            "subject": f"fs_account:{acct_id}",
            "credential_type": "bearer" if authorization.strip().lower().startswith("bearer ") else "api",
            "accounts": [
                {
                    "id": acct_id,
                    "freshservice_domain": matched.get("freshservice_domain"),
                    "status": matched.get("status"),
                    "default_workspace_id": matched.get("default_workspace_id"),
                }
            ],
            "scopes": ["read", "write"],
            "usage": {
                "integration_events_total": total_calls,
                "integration_events_succeeded": total_succeeded,
                "integration_events_failed": total_failed,
                "integration_events_last_24h": last_24h,
                "rate_limit": None,
                "quota": None,
            },
        }
    }
